// Librería Base OOP de Habilidades de Agentes v4.39 (FREQ_BREAK con presupuesto + informe que acusa por tasa)
(function() {
  // Version unica de la libreria. La cabecera de arriba y la seccion 0 del informe tienen que
  // decir lo mismo: el informe llego a anunciar v4.37 con la libreria ya en v4.38, que es justo el
  // dato que sirve para saber si la pestana recargo.
  var VERSION_LIB = 'v4.39';
  game.toastHistory = game.toastHistory || [];
  game.showToastsEnabled = (typeof game.showToastsEnabled !== 'undefined') ? game.showToastsEnabled : false;
  game.agents = game.agents || function() {};
  game.agents.showToasts = game.agents.showToasts || function(enable) {
    if (enable === undefined) return game.showToastsEnabled;
    game.showToastsEnabled = Boolean(enable);
    var status = game.showToastsEnabled ? 'ACTIVADAS' : 'DESACTIVADAS (silenciosas por defecto)';
    console.log('🔔 Notificaciones toast de agentes: ' + status);
    return game.showToastsEnabled;
  };
  game.showToasts = game.showToasts || game.agents.showToasts;
  game.noteTraces = game.noteTraces || {};

  game.toastLog = function() {
    if (!game.toastHistory.length) { console.log('Sin registro de toasts emitidos hasta el momento.'); return; }
    console.log('=== REGISTRO GLOBAL DE TOASTS EMITIDOS (' + game.toastHistory.length + ') ===');
    for (var i = 0; i < game.toastHistory.length; i++) console.log(game.toastHistory[i]);
  };

  // ── EFECTO MEDIDO DE CADA PELDANO ────────────────────────────────────────────────────────────
  // Por que existe: §21. Un peldano de la cadena de rescate se daba por cumplido por haberse
  // EJECUTADO, no por haber cambiado el mundo a mejor. minadoEmergencia devolvio "exito" 1178 veces
  // seguidas sin abrir una sola salida y el llamador (if (mined) return;) dejaba muertos los
  // peldanos de abajo. Nada de eso se veia: la traza dice que la accion OCURRIO, no que SIRVIERA.
  //
  // Aqui cada accion registrada queda PENDIENTE y se juzga ACCION_ESPERA_TICKS ticks despues:
  // hubo efecto si el agente gano cobertura (visited crecio) o cambio de celda. Es O(1) por accion
  // y sin console.log (§22): el resultado solo sale por game.informe().
  var ACCION_ESPERA_TICKS = 5;
  var MAX_PENDIENTES = 32;

  // Un peldano se anota al INTENTARLO, no al conseguirlo: minadoEmergencia solo llama a
  // logExecutionStep en su camino de exito, asi que las 1178 pasadas sin abrir salida no dejaban
  // ni una linea de telemetria — justo las que hacia falta contar. Los peldanos llaman a esto al
  // entrar y logExecutionStep vuelve a llamarlo si acaban bien; el deduplicado por (tick, tipo)
  // evita contar dos veces el mismo intento.
  function anotarAccion(a, tipo) {
    var v = a.vars;
    if (v.accionUltimoTick === a.stats.ticks && v.accionUltimoTipo === tipo) return;
    v.accionUltimoTick = a.stats.ticks;
    v.accionUltimoTipo = tipo;
    if (!v.acciones) v.acciones = {};
    var e = v.acciones[tipo];
    if (!e) {
      e = v.acciones[tipo] = { n: 0, conEfecto: 0, sinEfecto: 0, celdasGanadas: 0,
                               mismaPos: 0, rachaPos: 0, ultimaPos: null, celdaIman: null };
    }
    e.n++;
    var pos = a.x + ',' + a.y + ',' + a.z;
    if (e.ultimaPos === pos) e.rachaPos++; else e.rachaPos = 1;
    e.ultimaPos = pos;
    if (e.rachaPos > e.mismaPos) { e.mismaPos = e.rachaPos; e.celdaIman = pos; }
    if (!v.accionesPendientes) v.accionesPendientes = [];
    v.accionesPendientes.push({
      tipo: tipo, tick: a.stats.ticks, pos: pos,
      celdas: (v.visited && v.visited.size) || 0
    });
    if (v.accionesPendientes.length > MAX_PENDIENTES) v.accionesPendientes.shift();
  }

  // Se llama al principio de cada tick: resuelve las pendientes que ya tienen edad suficiente.
  function resolverAccionesPendientes(a) {
    var v = a.vars;
    var cola = v.accionesPendientes;
    if (!cola || !cola.length) return;
    var celdasAhora = (v.visited && v.visited.size) || 0;
    var posAhora = a.x + ',' + a.y + ',' + a.z;
    while (cola.length && (a.stats.ticks - cola[0].tick) >= ACCION_ESPERA_TICKS) {
      var p = cola.shift();
      var e = v.acciones && v.acciones[p.tipo];
      if (!e) continue;
      var ganadas = celdasAhora - p.celdas;
      if (ganadas > 0 || posAhora !== p.pos) {
        e.conEfecto++;
        if (ganadas > 0) e.celdasGanadas += ganadas;
      } else {
        e.sinEfecto++;
      }
    }
  }

  function logExecutionStep(a, actionType, details) {
    a.vars.executionTrace = a.vars.executionTrace || [];
    anotarAccion(a, actionType);
    var d = new Date();
    var timeStr = d.getHours() + ':' + String(d.getMinutes()).padStart(2,'0') + ':' + String(d.getSeconds()).padStart(2,'0') + '.' + String(d.getMilliseconds()).padStart(3,'0');
    a.vars.executionTrace.push({
      tick: a.stats.ticks,
      time: timeStr,
      pos: [a.x, a.y, a.z],
      dir: [a.vars.dir[0], a.vars.dir[1]],
      action: actionType,
      details: details || ''
    });
    if (a.vars.executionTrace.length > 500) a.vars.executionTrace.shift();
  }

  function attachNoteTrace(a, notePos, noteType, causeStr, callStackStr, extraInfo) {
    var posKey = notePos[0] + ',' + notePos[1] + ',' + notePos[2];
    var traceSnapshot = (a.vars.executionTrace || []).slice();
    game.noteTraces[posKey] = {
      noteType: noteType,
      agentName: a.name,
      agentId: a.id,
      runId: a.vars.runId,
      pos: notePos,
      tick: a.stats.ticks,
      cause: causeStr,
      callStack: callStackStr || 'onTick() -> ' + noteType + '() -> a.note()',
      grid3x3: get3x3HeightGridStr(a, notePos[0], notePos[2], notePos[1]),
      history: traceSnapshot,
      extra: extraInfo || {}
    };
  }

  game.traceNote = function(x, y, z) {
    var key = (typeof x === 'string') ? x : (x + ',' + y + ',' + z);
    var trace = game.noteTraces[key];
    if (!trace) {
      console.log('❌ No hay traza de nota registrada en [' + key + ']. Clave no encontrada o sin eventos activos.');
      return null;
    }
    console.log('=== TRAZA COMPLETA DE EJECUCIÓN DE NOTA: "' + trace.noteType + '" en [' + trace.pos + '] ===');
    console.log('Agente: ' + trace.agentName + ' (' + trace.agentId + ') | RunID: ' + trace.runId + ' | Emitida en Tick #' + trace.tick);
    console.log('Pila de Llamadas: ' + trace.callStack);
    console.log('Causa Declarada: ' + trace.cause);
    console.log(trace.grid3x3);
    console.log('--- HISTORIAL DE DECISIONES Y LLAMADAS DESDE EL INICIO (' + trace.history.length + ' PASOS) ---');
    for (var i = 0; i < trace.history.length; i++) {
      var h = trace.history[i];
      console.log('[' + h.time + ' | Tick ' + String(h.tick).padStart(3, '0') + '] ' + h.action.padEnd(14) + ' Pos:[' + h.pos + '] Dir:[' + h.dir + '] ' + h.details);
    }
    return trace;
  };

  game.onNote = function(fn) {
    game._onNoteListeners = game._onNoteListeners || [];
    if (typeof fn === 'function') game._onNoteListeners.push(fn);
  };

  game.purgeFlatPeakNotes = function() {
    if (typeof mc === 'undefined' || !mc.notes) return 0;
    var purged = 0;
    for (var key in mc.notes) {
      var txt = mc.notes[key];
      if (txt && txt.indexOf('visitas a la cima') >= 0 && txt.indexOf('⚠️ POSIBLE FALSO POSITIVO') >= 0) {
        delete mc.notes[key];
        purged++;
      }
    }
    console.log('🧹 Purga de notas completada: se han eliminado ' + purged + ' notas de cimas planas del mapa.');
    return purged;
  };

  function getAgentInstances() {
    if (typeof mc !== 'undefined' && mc.agents && typeof mc.agents.values === 'function') {
      return Array.from(mc.agents.values());
    }
    return [];
  }

  function processAgentBuildQueue(a) {
    if (!a.vars.buildQueue || !a.vars.buildQueue.length) {
      a.vars.isBuildingAsync = false;
      return;
    }
    a.vars.isBuildingAsync = true;

    // Procesar lote asíncrono unificado de hasta 3 bloques/pintados por frame en segundo plano
    var maxBatch = Math.min(3, a.vars.buildQueue.length);
    for (var i = 0; i < maxBatch; i++) {
      var item = a.vars.buildQueue.shift();
      if (item) {
        var obs1 = a.matId('obsidian'), obs2 = a.matId('obsidiana');
        if (item.action === 'paint') {
          var surfY = a.surfaceY(item.x, item.z);
          if (surfY >= 0) {
            var curFloor = a.getBlock(item.x, surfY, item.z);
            if ((!obs1 || curFloor !== obs1) && (!obs2 || curFloor !== obs2)) {
              if (typeof a.paint === 'function') a.paint(item.block, item.x, item.z);
            }
          }
        } else {
          var curB = a.getBlock(item.x, item.y, item.z);
          if ((!obs1 || curB !== obs1) && (!obs2 || curB !== obs2)) {
            a.setBlock(item.x, item.y, item.z, item.block);
            if (item.block === 0) {
              a.stats.mined = (a.stats.mined || 0) + 1;
            } else {
              a.stats.built = (a.stats.built || 0) + 1;
            }
          }
        }
      }
    }

    if (a.vars.buildQueue.length > 0) {
      if (typeof requestAnimationFrame === 'function') {
        requestAnimationFrame(function() { processAgentBuildQueue(a); });
      } else {
        setTimeout(function() { processAgentBuildQueue(a); }, 16);
      }
    } else {
      a.vars.isBuildingAsync = false;
    }
  }

  function calculateAgentDensity(ag, windowTicks) {
    var W = mc.dim.x, D = mc.dim.z;
    var grid = {};
    if (ag && ag.vars && ag.vars.recentVisits) {
      var minTick = windowTicks ? (ag.stats.ticks - windowTicks) : 0;
      for (var i = ag.vars.recentVisits.length - 1; i >= 0; i--) {
        var item = ag.vars.recentVisits[i];
        if (minTick > 0 && item.tick < minTick) break;
        var key = item.x + ',' + item.z;
        grid[key] = (grid[key] || 0) + 1;
      }
    }
    return grid;
  }

  function getHeatSymbol(count) {
    if (count <= 2) return '.';     // Tránsito fluido / Lineal
    if (count <= 5) return '░';     // Templado / Re-transito leve
    if (count <= 9) return '▒';     // Oscilación activa de zona
    return '█';                      // CRÍTICO: Atasco o bucle atrapado en micro-zona (10+ pasadas)
  }

  function calculateDynamicStuckThreshold(a) {
    var walkableLocalCount = 0;
    for (var dz = -2; dz <= 2; dz++) {
      for (var dx = -2; dx <= 2; dx++) {
        if (a.surfaceY(a.x + dx, a.z + dz) >= 0) walkableLocalCount++;
      }
    }
    return Math.max(8, Math.min(30, Math.round(walkableLocalCount * 1.2)));
  }

  function detectCyclePeriod(history) {
    var len = history.length;
    if (len < 16) return null;

    // 1. Strict periodic match (for short/exact loops)
    var maxPeriod = Math.floor(len / 2);
    for (var period = 8; period <= maxPeriod; period++) {
      var match = true;
      for (var i = 0; i < period; i++) {
        if (history[len - 1 - i] !== history[len - 1 - i - period]) { match = false; break; }
      }
      if (match) {
        var positions = new Set();
        for (var i = 0; i < period; i++) positions.add(history[len - 1 - i]);
        return { period: period, positions: positions };
      }
    }

    // 2. Fuzzy Set-Overlap match (detects large rectangular loops even with pauses/collisions)
    for (var windowSize = 12; windowSize <= Math.min(40, Math.floor(len / 2)); windowSize += 4) {
      var recentSet = new Set();
      var prevSet = new Set();
      for (var k = 0; k < windowSize; k++) {
        recentSet.add(history[len - 1 - k]);
        prevSet.add(history[len - 1 - k - windowSize]);
      }
      var overlap = 0;
      recentSet.forEach(function(pos) { if (prevSet.has(pos)) overlap++; });
      var ratio = overlap / recentSet.size;
      if (ratio >= 0.80 && recentSet.size >= 6) {
        var allPositions = new Set();
        recentSet.forEach(function(pos) { allPositions.add(pos); });
        prevSet.forEach(function(pos) { allPositions.add(pos); });
        return { period: windowSize * 2, positions: allPositions };
      }
    }

    return null;
  }

  function findExistingNoteInRadius(a, headerKey, radius) {
    if (typeof a.getNote !== 'function') return null;
    var r = radius || 2;
    for (var dy = -r; dy <= r; dy++) {
      for (var dz = -r; dz <= r; dz++) {
        for (var dx = -r; dx <= r; dx++) {
          var nx = a.x + dx, ny = a.y + dy, nz = a.z + dz;
          if (nx >= 0 && nx < mc.dim.x && ny >= 0 && ny < mc.dim.y && nz >= 0 && nz < mc.dim.z) {
            var note = a.getNote(nx, ny, nz);
            if (note && note.indexOf(headerKey) >= 0) {
              return { note: note, pos: [nx, ny, nz] };
            }
          }
        }
      }
    }
    return null;
  }

  // Una nota es un post-it de 280 caracteres (MC_NOTE_MAX) y mcAgentNoteForce hace slice() a pelo: lo que
  // sobra se pierde A MEDIA LINEA. Las notas de cima con 4 agentes se estaban comiendo justo la cuadricula
  // de cotas, que es la parte util. Aqui se monta al reves: lo obligatorio primero y lo opcional se anade
  // solo mientras quepa entero, asi que una nota corta explica menos pero nunca sale mutilada.
  function componerNota(a, obligatorias, opcionales) {
    var tope = (typeof MC_NOTE_MAX !== 'undefined' ? MC_NOTE_MAX : 280) - ('[' + a.id + '] ').length;
    var txt = obligatorias.join('\n');
    for (var i = 0; i < (opcionales || []).length; i++) {
      if (txt.length + 1 + opcionales[i].length > tope) continue;
      txt += '\n' + opcionales[i];
    }
    return txt;
  }

  function get3x3HeightGridStr(a, cx, cz, centerY) {
    var lines = ['Cotas 3x3 (Centro Y=' + centerY + '):'];
    for (var dz = -1; dz <= 1; dz++) {
      var row = 'Z' + (dz === 0 ? '=0' : (dz > 0 ? '+' + dz : dz)) + ': ';
      for (var dx = -1; dx <= 1; dx++) {
        var nx = cx + dx, nz = cz + dz;
        var ny = a.surfaceY(nx, nz);
        var mark = (dx === 0 && dz === 0) ? '*' : '';
        row += ny + mark + (dx < 1 ? ' ' : '');
      }
      lines.push(row);
    }
    return lines.join('\n');
  }

  // El criterio de atasco vive aqui, separado de la impresion, porque lo comparten game.stuck() (que
  // lo saca por consola) y game.informe() (que lo mete en el informe). Devuelve null si el agente
  // esta sano; si no, la ficha del atasco. NO imprime y NO escribe en el mundo.
  function diagnosticarAtasco(a) {
    if (!a || !a.vars || !a.vars.recentVisits) return null;

    var grid = calculateAgentDensity(a, 50);
    var curKey = a.x + ',' + a.z;
    var curVisits = grid[curKey] || 0;

    var localVisits = 0;
    var localCells = 0;
    for (var dz = -2; dz <= 2; dz++) {
      for (var dx = -2; dx <= 2; dx++) {
        var k = (a.x + dx) + ',' + (a.z + dz);
        if (grid[k]) {
          localVisits += grid[k];
          localCells++;
        }
      }
    }

    var peakNoteObj = findExistingNoteInRadius(a, 'visitas a la cima', 2) || findExistingNoteInRadius(a, 'pino de emergencia', 2);
    // El atasco se MIDE; una nota cercana solo ETIQUETA. La nota es el registro de un SITIO y vive para
    // siempre en mc.notes, asi que con `peakNoteObj !== null` dentro del OR cualquiera que pasara a 2
    // celdas daba positivo aunque fuera caminando tan campante. El umbral fijo de 4 pasos hacia lo mismo
    // por otro lado: pisaba al dinamico que se calcula aqui al lado (8..30 segun terreno pisable).
    var umbral = calculateDynamicStuckThreshold(a);
    var pasos = a.vars.stepsWithoutNewCell || 0;
    var motivo = null;
    if (curVisits >= 6) motivo = 'pasadas por la celda actual ' + curVisits + ' (>=6)';
    else if (localVisits >= 12 && localCells <= 3) motivo = 'densidad local ' + localVisits + ' pasadas en ' + localCells + ' celdas';
    else if (pasos >= umbral) motivo = 'pasos sin celda nueva ' + pasos + '/' + umbral;
    if (!motivo) return null;

    var level = (curVisits >= 10 ? '█ ATASCO CRÍTICO (10+)' : (curVisits >= 6 ? '▒ OSCILACIÓN ALTA' : '░ ENTRAPAMIENTO LOCAL'));
    if (peakNoteObj) level += ' 🌲(nota de cima a <=2)';
    return {
      id: a.id,
      agente: a.name,
      posicion: '[' + a.x + ',' + a.y + ',' + a.z + ']',
      visitasRecientes: curVisits,
      pasosSinProgreso: pasos + '/' + umbral,
      nivelAlert: level,
      motivo: motivo,
      critico: curVisits >= 10
    };
  }

  game.stuck = function() {
    var agents = getAgentInstances();
    var stuckList = [];

    for (var i = 0; i < agents.length; i++) {
      var ficha = diagnosticarAtasco(agents[i]);
      if (ficha) stuckList.push(ficha);
    }

    console.log('=== DIAGNÓSTICO DIRECTO DE AGENTES EN ATASCO ACTIVO (' + stuckList.length + ') ===');
    if (!stuckList.length) {
      console.log('✅ Ningún agente se encuentra actualmente atrapado en bucle u oscilación.');
    } else {
      console.table(stuckList);
    }
    return stuckList;
  };

  game.heatmap = function(windowTicks) {
    var W = mc.dim.x, D = mc.dim.z;
    var agents = getAgentInstances();
    var combinedGrid = {};
    var agentPositions = {};

    if (agents && agents.length) {
      for (var aIdx = 0; aIdx < agents.length; aIdx++) {
        var ag = agents[aIdx];
        if (ag && ag.vars && ag.vars.recentVisits) {
          var initialChar = (ag.name || ag.id || 'A').charAt(0).toUpperCase();
          agentPositions[ag.x + ',' + ag.z] = initialChar;
          var grid = calculateAgentDensity(ag, windowTicks);
          for (var key in grid) {
            combinedGrid[key] = (combinedGrid[key] || 0) + grid[key];
          }
        }
      }
    }

    var modeTitle = windowTicks ? ('Últimos ' + windowTicks + ' Ticks / ~' + Math.round(windowTicks*0.2) + 's') : 'Acumulado Total de Pasadas Físicas';
    var lines = ['=== REJILLA 2D DEL MAPA DE CALOR DE OSCILACIÓN (' + modeTitle + ') ==='];
    var header = '  [Z\\X] ';
    for (var x = 0; x < W; x++) header += (x % 10);
    lines.push(header);

    for (var z = 0; z < D; z++) {
      var row = (' Z=' + String(z).padStart(2, '0') + ': ').substring(0, 8);
      for (var x = 0; x < W; x++) {
        var posKey = x + ',' + z;
        if (agentPositions[posKey]) {
          row += agentPositions[posKey];
        } else {
          var count = combinedGrid[posKey] || 0;
          row += getHeatSymbol(count);
        }
      }
      lines.push(row);
    }
    lines.push('LEYENDA: . = Tránsito Fluido (1-2) | ░ = Templado (3-5) | ▒ = Oscilación (6-9) | █ = 🔥 ATASCO CRÍTICO (10+) | Letras = Inicial del Agente');
    var out = lines.join('\n');
    console.log(out);
    return out;
  };

  function getMatName(blockId) {
    if (!blockId) return 'aire';
    if (typeof mc !== 'undefined' && mc.blockKey && mc.blockKey[blockId]) {
      var key = mc.blockKey[blockId];
      if (typeof key === 'string' && key.indexOf('asset:assets/') === 0) {
        key = key.replace('asset:assets/', '').replace('.vox.json', '');
      }
      return key;
    }
    return 'id_' + blockId;
  }

  // ── REGISTRO DE ESCRITURAS DEL MUNDO ─────────────────────────────────────────────────────────
  // Por que existe: el atasco mas dificil de ver no es de un agente, es ENTRE agentes. Uno pica el
  // bloque que le tapia la salida y otro se lo repone en el mismo sitio dos ticks despues; los dos
  // creen estar progresando y ninguna traza individual lo delata. Este anillo guarda QUIEN escribio
  // QUE en CADA celda, que es lo unico que responde "quien repone lo que otro pica".
  //
  // Se alimenta desde los envoltorios de a.setBlock/a.paint que ya existen (proteccion de
  // obsidiana): es el unico sitio por el que pasan TODAS las escrituras de agente, incluida la cola
  // asincrona de construccion. Solo se anota si el bloque CAMBIO de verdad.
  var MAX_ESCRITURAS = 600;
  game.worldWrites = game.worldWrites || [];

  function anotarEscritura(a, x, y, z, antes, despues) {
    game.worldWrites.push({
      ms: performance.now(), tick: a.stats.ticks, agente: a.name || a.id,
      x: x, y: y, z: z, de: getMatName(antes), a: getMatName(despues)
    });
    if (game.worldWrites.length > MAX_ESCRITURAS) game.worldWrites.shift();
  }

  // ── INFORME DE ATASCOS · game.informe() ──────────────────────────────────────────────────────
  // Por que existe: los diagnosticos que ya habia (game.stuck, game.heatmap, showTickets,
  // traceNote) dicen DONDE esta el agente, nunca POR QUE su rescate no funciona. Los tres fallos
  // de §21 se cazaron leyendo codigo, no leyendo diagnosticos. Este informe es el instrumento que
  // faltaba: un texto autosuficiente que se genera desde F12 y se pasa tal cual a quien depura.
  //
  // El liston es que el informe SOLO, sin abrir el codigo, hubiera delatado los tres fallos:
  //   minado que declara exito sin abrir paso  -> 3.3, peldano con N intentos y 0 celdas ganadas
  //   picando siempre desde la misma celda     -> 3.3, columna "misma celda"
  //   salto tactico que nunca elige destino    -> 3.3, peldano con intentos y 0 con efecto
  //   otro agente repone lo que este pica      -> 4, escrituras del mundo con autor por celda
  //
  // NORMA (§23): toda hipotesis de la seccion 2 cita el § de REGLAS_AGENTES.md que la respalda, o
  // no se imprime. Un informe que opina sin respaldo es ruido, y el ruido ya costo 1178 lineas.
  //
  //   game.informe()                     // todos; guarda en el servidor y devuelve el string
  //   game.informe({ guardar:false })    // solo devuelve -> copy(game.informe({guardar:false}))
  //   game.informe({ agentes:['constructor'], ticks:400, max:30000, todos:true })
  //   game.informe.ultimo                // el ultimo generado, por si se perdio el scroll
  var INFORME_MAX = 30000;
  var INFORME_TICKS = 400;
  var INFORME_CAJA_MAX = 24;   // lado maximo del heatmap recortado

  function huellaLibreria() {
    // Para no depurar codigo que ya no corre: si el informe llega de una pestana que no recargo
    // tras editar la libreria, la huella no coincide con la del fichero y se ve al instante.
    var src = '';
    try {
      src = String(logExecutionStep) + String(game.skills.minadoEmergencia) +
            String(game.skills.saltoTactico) + String(game.skills.vecinosPisablesEn);
    } catch (e) { return 'n/d'; }
    var h = 5381;
    for (var i = 0; i < src.length; i++) h = (((h << 5) + h) ^ src.charCodeAt(i)) >>> 0;
    return h.toString(36);
  }

  function otrosAgentesEn(x, z, yo) {
    var out = [], ags = getAgentInstances();
    for (var i = 0; i < ags.length; i++) {
      var o = ags[i];
      if (o !== yo && o.x === x && o.z === z) out.push(o.name || o.id);
    }
    return out;
  }

  // Version de SOLO LECTURA de isTrapPit: la de game.skills ESCRIBE una nota en el mundo cuando
  // acierta (recordTrapPitVisit). Un informe no puede modificar lo que esta diagnosticando.
  function esFosoLectura(a, nx, nz) {
    var W = mc.dim.x, D = mc.dim.z;
    var ny = a.surfaceY(nx, nz);
    if (ny < 0) return false;
    if (ny >= a.surfaceY(a.x, a.z)) return false;
    var climb = a.climb || 1;
    var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
    for (var k = 0; k < 4; k++) {
      var tx = nx + dirs[k][0], tz = nz + dirs[k][1];
      if (tx < 1 || tx >= W - 1 || tz < 1 || tz >= D - 1) continue;
      var ty = a.surfaceY(tx, tz);
      if (ty >= 0 && (ty - ny) <= climb) return false;
    }
    return true;
  }

  // Por que el agente no puede pisar (x,z). Devuelve codigo legible + simbolo para la rejilla 5x5.
  function razonVecino(a, x, z) {
    var m = (a.margin === undefined) ? 1 : a.margin;
    if (x < m || z < m || x >= mc.dim.x - m || z >= mc.dim.z - m) {
      return { cod: 'BORDE_MAPA', sim: 'B', y: -1, mat: '-' };
    }
    var climb = (a.climb === undefined) ? 1 : a.climb;
    var drop = (a.drop === undefined) ? 3 : a.drop;
    // Se pregunta con mcSurfaceNear, que es LO QUE USA EL FRAMEWORK (suelo pisable a +climb/-drop
    // de a.y). a.surfaceY es el solido mas alto de la columna y bajo un techo devuelve algo metros
    // por encima de la cabeza: puntuar con eso es el fallo de §21 otra vez.
    var ny = (typeof mcSurfaceNear === 'function') ? mcSurfaceNear(x, z, a.y, climb, drop) : -1;
    if (ny >= 0) {
      // El paso NO lo decide solo mcSurfaceNear: la libreria envuelve a.canWalk con desnivelProhibido
      // (§15), que mide CIMA contra CIMA. Un vecino con suelo pisable pero con voladizo encima se
      // rechaza porque el paso acabaria en la azotea. Sin esto el informe imprimia "LIBRE ·
      // canWalk=false", que es justo la contradiccion que no puede permitirse (§23).
      var cimaAqui = a.surfaceY(a.x, a.z), cimaAlli = a.surfaceY(x, z);
      if (cimaAqui >= 0 && cimaAlli >= 0) {
        var salto = cimaAlli - cimaAqui;
        var matCima = getMatName(a.getBlock(x, cimaAlli, z));
        if (salto > climb) {
          return { cod: 'AZOTEA +' + salto + ' (suelo pisable en y=' + ny + ', pero la cima esta en y=' +
                        cimaAlli + ': el paso acabaria arriba y climb=' + climb + ')',
                   sim: '^', y: cimaAlli, mat: matCima };
        }
        if (salto < -drop) {
          return { cod: 'DESPLOME ' + salto + ' (drop=' + drop + ')', sim: 'v', y: cimaAlli, mat: matCima };
        }
      }
      var mat = getMatName(a.getBlock(x, ny, z));
      var quien = otrosAgentesEn(x, z, a);
      if (quien.length) return { cod: 'OCUPADA por ' + quien.join('/'), sim: 'A', y: ny, mat: mat };
      if (esFosoLectura(a, x, z)) return { cod: 'FOSO_TRAMPA', sim: 'P', y: ny, mat: mat };
      return { cod: 'LIBRE', sim: '.', y: ny, mat: mat };
    }
    var top = a.surfaceY(x, z);
    if (top < 0) return { cod: 'SIN_SUELO', sim: '_', y: -1, mat: '-' };
    var matTop = getMatName(a.getBlock(x, top, z));
    // Hay solido a una cota alcanzable pero con mas solido encima: es un MURO, y es justo el caso
    // que la cadena de rescate intenta picar. Distinguirlo de un desnivel importa: uno se pica, el
    // otro no se arregla picando.
    for (var y = a.y + climb; y >= a.y - drop; y--) {
      if (y < 0 || y >= mc.dim.y) continue;
      if (a.getBlock(x, y, z) !== 0) {
        return { cod: 'TAPIADO (solido en y=' + y + ')', sim: '#', y: top, mat: matTop };
      }
    }
    if (top > a.y + climb) return { cod: 'DESNIVEL +' + (top - a.y), sim: '^', y: top, mat: matTop };
    return { cod: 'DESNIVEL -' + (a.y - top), sim: 'v', y: top, mat: matTop };
  }

  function comprimirTraza(trace, n) {
    var out = [], ult = null;
    var ini = Math.max(0, trace.length - n);
    for (var i = ini; i < trace.length; i++) {
      var e = trace[i];
      var clave = e.action + '|' + e.pos.join(',');
      if (ult && ult.clave === clave) { ult.n++; ult.hasta = e.tick; continue; }
      ult = { clave: clave, n: 1, tick: e.tick, hasta: e.tick, action: e.action,
              pos: e.pos.join(','), details: e.details };
      out.push(ult);
    }
    return out.map(function(e) {
      var rep = e.n > 1 ? ('  x' + e.n + ' (t' + e.tick + '..' + e.hasta + ')') : ('  (t' + e.tick + ')');
      return '  ' + e.action + ' [' + e.pos + ']' + rep + (e.n > 1 ? '' : (e.details ? '  ' + e.details : ''));
    });
  }

  // Escrituras del mundo agrupadas por celda. Solo celdas con >=3 cambios: lo demas es construccion
  // normal y no dice nada.
  function escriturasPorCelda(minCambios) {
    var porCelda = {};
    var w = game.worldWrites || [];
    for (var i = 0; i < w.length; i++) {
      var e = w[i];
      var k = e.x + ',' + e.y + ',' + e.z;
      var g = porCelda[k] || (porCelda[k] = { k: k, n: 0, autores: {}, seq: [] });
      g.n++;
      g.autores[e.agente] = (g.autores[e.agente] || 0) + 1;
      if (g.seq.length < 8) g.seq.push(e.agente.charAt(0) + ':' + e.a);
    }
    var out = [];
    for (var k2 in porCelda) if (porCelda[k2].n >= minCambios) out.push(porCelda[k2]);
    out.sort(function(x, y) { return y.n - x.n; });
    return out;
  }

  function seccionAgente(a, atasco, ticks, piezas) {
    var v = a.vars || {};
    var L = [];
    var titulo = (a.name || a.id) + ' (' + a.id + ')';
    L.push('');
    L.push('### ' + titulo + ' — ' + (atasco ? atasco.nivelAlert : 'sano'));

    // 3.1 identidad y configuracion
    var sk = (a.cfg && a.cfg.skills) || v.skills || {};
    var on = [], off = [];
    for (var s in sk) (sk[s] ? on : off).push(s);
    L.push('- pos [' + a.x + ',' + a.y + ',' + a.z + ']  dir ' + getCardinalName(v.dir) +
           '  estado ' + a.state + '  bloque ' + a.block);
    L.push('- tickMs ' + a.tickMs + '  climb ' + a.climb + '  drop ' + a.drop + '  margin ' + a.margin);
    L.push('- skills ON: ' + (on.length ? on.join(', ') : '(ninguna)'));
    L.push('- skills OFF: ' + (off.length ? off.join(', ') : '(ninguna)'));
    if (atasco) L.push('- motivo medido: ' + atasco.motivo);

    // 3.2 progreso + curva de cobertura
    L.push('');
    L.push('**Progreso**  ticks ' + a.stats.ticks + ' · pasos ' + a.stats.steps + ' · bloqueos ' +
           a.stats.blocked + ' · picados ' + (a.stats.mined || 0) + ' · celdas 3D ' +
           (v.visited ? v.visited.size : 0) + ' · sin celda nueva ' + (v.stepsWithoutNewCell || 0));
    var pr = v.progreso || [];
    if (pr.length) {
      var curva = pr.map(function(p) { return 't' + p.tick + ':' + p.celdas; }).join(' ');
      L.push('Cobertura (cada 25 ticks): ' + curva);
      var gan = pr[pr.length - 1].celdas - pr[0].celdas;
      var lapso = pr[pr.length - 1].tick - pr[0].tick;
      L.push('  -> ' + gan + ' celdas nuevas en los ultimos ' + lapso + ' ticks');
    } else {
      L.push('Cobertura: sin muestras todavia (hacen falta 25 ticks).');
    }

    // 3.3 escalera de rescate: el corazon del informe
    L.push('');
    L.push('**Escalera de rescate — efecto MEDIDO, no intentos** (§6, §21)');
    L.push('| accion | veces | con efecto | sin efecto | celdas ganadas | celdas/vez | misma celda | veredicto |');
    L.push('|---|---|---|---|---|---|---|---|');
    var acc = v.acciones || {};
    var claves = Object.keys(acc).sort(function(x, y) { return acc[y].n - acc[x].n; });
    for (var i = 0; i < claves.length; i++) {
      var e = acc[claves[i]];
      var juzgadas = e.conEfecto + e.sinEfecto;
      var tasa = juzgadas ? (e.celdasGanadas / juzgadas) : 0;
      var ver = '—';
      if (juzgadas >= 5) {
        // "Cambio de celda" NO es efecto por si solo: una serpiente que hace ping-pong entre dos
        // celdas cambia de celda siempre y no avanza nunca (§21 otra vez, ahora dentro del informe).
        //
        // Y el cero exacto tampoco vale como criterio. El informe del 30/7 salio con ~100 filas y
        // TODAS decian "ok" mientras los 5 agentes llevaban 975 ticks sin descubrir una celda: el
        // peldano culpable, FREQ_BREAK, gano 110 celdas en 19215 ejecuciones y por no ser 0 exacto
        // paso por bueno. Lo que separa a un peldano util de uno esteril no es el cero, es el ORDEN
        // DE MAGNITUD: en ese mismo informe WALK daba 4,3 celdas por ejecucion y FREQ_BREAK 0,006.
        if (e.conEfecto === 0) ver = '**INEFICAZ**';
        else if (juzgadas >= 10 && e.celdasGanadas === 0) ver = '**SIN AVANCE**';
        else if (juzgadas >= TASA_MIN_JUZGADAS && tasa < TASA_ESTERIL) ver = '**ESTÉRIL**';
        else if (e.conEfecto * 4 < juzgadas) ver = 'flojo';
        else ver = 'ok';
      }
      L.push('| ' + claves[i] + ' | ' + e.n + ' | ' + e.conEfecto + ' | ' + e.sinEfecto + ' | ' +
             e.celdasGanadas + ' | ' + tasa.toFixed(3) + ' | ' +
             e.mismaPos + (e.celdaIman ? ' @[' + e.celdaIman + ']' : '') +
             ' | ' + ver + ' |');
    }
    if (!claves.length) L.push('| (sin acciones registradas) | | | | | | | |');
    // "veces" son INTENTOS; el veredicto solo mira las ya juzgadas. La diferencia son las que aun
    // no han cumplido su plazo de espera — se dice, para que las columnas cuadren a la vista.
    var pendientes = (v.accionesPendientes && v.accionesPendientes.length) || 0;
    if (pendientes) L.push('(' + pendientes + ' accion' + (pendientes === 1 ? '' : 'es') +
                           ' aun sin juzgar: no han cumplido los ' + ACCION_ESPERA_TICKS + ' ticks de espera)');

    // 3.4 vecindario 5x5
    L.push('');
    L.push('**Vecindario 5x5** (@ = agente · . libre · # tapiado · ^ desnivel+ · v desnivel- · _ sin suelo · B borde · P foso · A otro agente)');
    var filas = [];
    var razones4 = [];
    for (var dz = -2; dz <= 2; dz++) {
      var fila = '  ';
      for (var dx = -2; dx <= 2; dx++) {
        if (dx === 0 && dz === 0) { fila += ' @'; continue; }
        var r = razonVecino(a, a.x + dx, a.z + dz);
        fila += ' ' + r.sim;
        if (Math.abs(dx) + Math.abs(dz) === 1) razones4.push({ d: [dx, dz], r: r });
      }
      filas.push(fila + '   z=' + (a.z + dz));
    }
    L.push('```');
    L.push('  x=' + (a.x - 2) + ' .. x=' + (a.x + 2));
    for (var f = 0; f < filas.length; f++) L.push(filas[f]);
    L.push('```');
    L.push('Ortogonales (las unicas que decide canWalk):');
    var libres = 0;
    for (var q = 0; q < razones4.length; q++) {
      var rr = razones4[q];
      var puede = a.canWalk(rr.d[0], rr.d[1]);
      if (puede) libres++;
      L.push('- ' + getCardinalName(rr.d) + ' (' + (a.x + rr.d[0]) + ',' + (a.z + rr.d[1]) + ') cima y=' +
             rr.r.y + ' ' + rr.r.mat + ' — ' + rr.r.cod + ' · canWalk=' + puede);
    }
    L.push('Vecinos pisables: ' + libres + '/4');

    // 3.5 heatmap recortado a la caja de merodeo
    var grid = calculateAgentDensity(a, ticks);
    var x0 = 1e9, x1 = -1e9, z0 = 1e9, z1 = -1e9, celdas = 0;
    for (var kk in grid) {
      var p = kk.split(','), px = +p[0], pz = +p[1];
      if (px < x0) x0 = px; if (px > x1) x1 = px;
      if (pz < z0) z0 = pz; if (pz > z1) z1 = pz;
      celdas++;
    }
    var heat = [];
    // La CAJA DE MERODEO es el bbox real de lo pisado (con margen 3, dentro del mapa): es la que se
    // compara contra las celdas distintas, y la que juzga R8. La VENTANA es solo lo que se dibuja.
    var dimX = (mc.dim && mc.dim.x) || 96, dimZ = (mc.dim && mc.dim.z) || 96;
    if (celdas) {
      x0 = Math.max(0, Math.round(x0) - 3); x1 = Math.min(dimX - 1, Math.round(x1) + 3);
      z0 = Math.max(0, Math.round(z0) - 3); z1 = Math.min(dimZ - 1, Math.round(z1) + 3);
    }
    if (celdas) {
      var area = (x1 - x0 + 1) * (z1 - z0 + 1);
      var wx0 = x0, wx1 = x1, wz0 = z0, wz1 = z1, recorteHeat = '';
      var mitad = Math.round(INFORME_CAJA_MAX / 2);
      if (x1 - x0 > INFORME_CAJA_MAX) { wx0 = Math.max(x0, a.x - mitad); wx1 = Math.min(x1, a.x + mitad); }
      if (z1 - z0 > INFORME_CAJA_MAX) { wz0 = Math.max(z0, a.z - mitad); wz1 = Math.min(z1, a.z + mitad); }
      var dibujadas = 0;
      for (var kk2 in grid) {
        var p2 = kk2.split(','), qx = +p2[0], qz = +p2[1];
        if (qx >= wx0 && qx <= wx1 && qz >= wz0 && qz <= wz1) dibujadas++;
      }
      if (wx0 !== x0 || wx1 !== x1 || wz0 !== z0 || wz1 !== z1) {
        recorteHeat = ' · ventana dibujada x[' + wx0 + '..' + wx1 + '] z[' + wz0 + '..' + wz1 +
                      '] (' + INFORME_CAJA_MAX + ' de lado alrededor del agente): se ven ' +
                      dibujadas + ' de las ' + celdas + ' celdas';
      }
      heat.push('');
      heat.push('**Merodeo** — caja x[' + x0 + '..' + x1 + '] z[' + z0 + '..' + z1 + '] · ' +
                celdas + ' celdas distintas / ' + area + ' de la caja (' +
                Math.round(100 * celdas / Math.max(area, 1)) + '%)' + recorteHeat);
      heat.push('```');
      for (var hz = wz0; hz <= wz1; hz++) {
        var row = '';
        for (var hx = wx0; hx <= wx1; hx++) {
          if (hx === a.x && hz === a.z) { row += '@'; continue; }
          var nv = grid[hx + ',' + hz] || 0;
          row += nv ? getHeatSymbol(nv) : ' ';   // ' ' = nunca pisada; getHeatSymbol da '.' a 1-2
        }
        heat.push(row + ' z=' + hz);
      }
      heat.push('```');
    }

    // 3.6 traza comprimida
    var traza = [];
    var tr = v.executionTrace || [];
    if (tr.length) {
      traza.push('');
      traza.push('**Traza** (ultimas 40 entradas, comprimidas por repeticion)');
      traza.push('```');
      var comp = comprimirTraza(tr, 40);
      for (var t = 0; t < comp.length; t++) traza.push(comp[t]);
      traza.push('```');
    }

    // 3.7 notas cercanas: son el razonamiento del agente, van INTEGRAS (una nota resumida ya no
    // explica nada). Lo que se acota es cuantas: las 3 mas cercanas, y se dice cuantas se dejaron.
    var notas = [];
    if (typeof mc !== 'undefined' && mc.notes) {
      var cand = [];
      for (var nk in mc.notes) {
        var np = nk.split(',');
        var dxn = Math.abs(+np[0] - a.x), dzn = Math.abs(+np[2] - a.z);
        if (dxn <= 4 && dzn <= 4) cand.push({ k: nk, d: dxn + dzn + Math.abs(+np[1] - a.y), txt: mc.notes[nk] });
      }
      cand.sort(function(p, q) { return p.d - q.d; });
      for (var cn = 0; cn < Math.min(cand.length, 3); cn++) {
        notas.push('- [' + cand[cn].k + '] ' + cand[cn].txt);
      }
      if (cand.length > 3) notas.push('_(' + (cand.length - 3) + ' notas mas a <=4 celdas, omitidas)_');
    }
    if (notas.length) { notas.unshift('**Notas a <=4 celdas**'); notas.unshift(''); }

    // 3.8 tickets deduplicados
    var tks = [];
    if (v.tickets) {
      var mot = Object.keys(v.tickets).filter(function(m) { return v.tickets[m] > 0; });
      if (mot.length) {
        tks.push('');
        tks.push('**Tickets** ' + mot.map(function(m) { return m + ' x' + v.tickets[m]; }).join(' · '));
      }
    }

    piezas.push({ cat: atasco ? 'fijo' : 'sano', txt: L.join('\n'), agente: titulo });
    if (heat.length) piezas.push({ cat: atasco ? 'heatmap' : 'sano', txt: heat.join('\n'), agente: titulo });
    if (traza.length) piezas.push({ cat: atasco ? 'traza' : 'sano', txt: traza.join('\n'), agente: titulo });
    if (notas.length) piezas.push({ cat: atasco ? 'notas' : 'sano', txt: notas.join('\n'), agente: titulo });
    if (tks.length) piezas.push({ cat: atasco ? 'tickets' : 'sano', txt: tks.join('\n'), agente: titulo });

    var areaCaja = celdas ? Math.round((x1 - x0 + 1) * (z1 - z0 + 1)) : 0;
    return { libres: libres, celdas: celdas, area: areaCaja, razones4: razones4, acc: acc };
  }

  // Reglas de hipotesis. Cada una cita el § de REGLAS_AGENTES.md que la respalda o no se imprime.
  function hipotesis(fichas, resumenes) {
    var H = [];
    for (var i = 0; i < fichas.length; i++) {
      var a = fichas[i].a, at = fichas[i].atasco, R = resumenes[i];
      if (!R) continue;
      var nom = a.name || a.id;
      var acc = R.acc;
      // R1 y R2 NO se condicionan a que el detector marque atasco: son medidas propias. La serpiente
      // que hacia ping-pong andaba en cada tick, asi que el detector la daba por sana mientras llevaba
      // 975 ticks sin ganar una celda. Las demas reglas si dependen del atasco medido.

      var mejor = null;                                       // el peldano mas productivo del agente
      for (var km in acc) {
        var em = acc[km], jm = em.conEfecto + em.sinEfecto;
        if (jm >= TASA_MIN_JUZGADAS && (!mejor || (em.celdasGanadas / jm) > mejor.tasa)) {
          mejor = { k: km, tasa: em.celdasGanadas / jm };
        }
      }
      for (var k in acc) {                                    // R1 + R2
        var e = acc[k];
        var juzgadasR = e.conEfecto + e.sinEfecto;
        if (e.n >= 10 && e.conEfecto > 0 && juzgadasR >= 10 && e.celdasGanadas === 0) {
          H.push('R1 · ' + nom + ': **' + k + '** se ejecuto ' + e.n + ' veces y el agente cambio de celda ' +
                 'casi siempre, pero **gano 0 celdas nuevas**: va y vuelve entre las mismas casillas. ' +
                 'Moverse no es avanzar (§21.1).');
        }
        if (e.n >= 10 && e.conEfecto === 0 && juzgadasR >= 5) {
          H.push('R1 · ' + nom + ': **' + k + '** se ejecuto ' + e.n +
                 ' veces y NO produjo ni una celda nueva ni un cambio de celda (§21.1: un peldano ' +
                 'solo cuenta si el mundo cambio a mejor).');
        }
        // R1 por TASA: el peldano se mueve y hasta gana alguna celda suelta, pero a un ritmo que no
        // se parece al de un peldano que funciona. Se cita el mejor del propio agente para que la
        // comparacion no dependa de un numero magico de este codigo.
        if (juzgadasR >= TASA_MIN_JUZGADAS && e.conEfecto > 0 && e.celdasGanadas > 0 &&
            (e.celdasGanadas / juzgadasR) < TASA_ESTERIL) {
          H.push('R1 · ' + nom + ': **' + k + '** se ejecuto ' + e.n + ' veces para ganar ' +
                 e.celdasGanadas + ' celdas = **' + (e.celdasGanadas / juzgadasR).toFixed(3) +
                 ' celdas por vez**' + (mejor ? ', cuando **' + mejor.k + '** da ' +
                 mejor.tasa.toFixed(2) + ' en el mismo agente' : '') +
                 '. Moverse no es avanzar (§21.1).');
        }
        // R2 ya no cuelga de R1: colgaba del caso "no cambio de celda", que es justo el que NO se da
        // en un peldano que camina, asi que la regla era inalcanzable y no salio nunca en un informe
        // real (habia candidatas de sobra: UTURN_DEADEND, 48 repeticiones desde la misma celda).
        if (e.mismaPos >= 10) {
          H.push('R2 · ' + nom + ': **' + k + '** se repitio ' + e.mismaPos + ' veces seguidas desde ' +
                 'la MISMA celda [' + e.celdaIman + '] (§6: el peldano no esta desatascando, esta ' +
                 'girando en vacio).');
        }
      }

      if (R.libres === 0) {                                   // R5
        var todasDesnivel = true;
        for (var q = 0; q < R.razones4.length; q++) {
          if (R.razones4[q].r.cod.indexOf('DESNIVEL') !== 0) { todasDesnivel = false; break; }
        }
        if (todasDesnivel && R.razones4.length === 4) {
          H.push('R5 · ' + nom + ': 0 vecinos pisables y las 4 razones son DESNIVEL. Esto NO es la ' +
                 'heuristica, es climb=' + a.climb + '/drop=' + a.drop + ' (§15): con esos limites la ' +
                 'celda es inalcanzable y ninguna politica lo arregla.');
        }
      }

      if (!at) continue;                                      // de aqui abajo hace falta atasco medido

      var sk = (a.cfg && a.cfg.skills) || (a.vars && a.vars.skills) || {};
      if (at.critico && sk.saltoTactico === false) {          // R6
        H.push('R6 · ' + nom + ': atasco critico con saltoTactico DESACTIVADO. La escalera de §6 se ' +
               'queda sin ultimo recurso: desvio y minado ya se agotaron y no hay peldano debajo.');
      }

      // R8: cubre poco de la zona por la que se mueve. El area minima evita que dispare con una caja
      // de 3x3, donde el porcentaje no significa nada.
      //
      // El suelo estaba en 100 y eso lo invertia: la caja de merodeo la dibuja el propio agente, asi
      // que cuanto MAS atascado, mas pequena, y menos posible era que la regla hablara. En el informe
      // del 30/7 los cinco atascados tenian cajas de 48..72 celdas (uno pisaba 6 de 72 = 8%) y R8 no
      // salio ni una vez. 25 = 5x5, que sigue dejando fuera la caja de 3x3 del comentario de arriba.
      if (R.celdas && R.area >= 25 && (R.celdas / R.area) < 0.25) {
        H.push('R8 · ' + nom + ': solo pisa ' + R.celdas + ' celdas de las ' + R.area +
               ' de su caja de merodeo (' + Math.round(100 * R.celdas / R.area) + '%): recorre lineas ' +
               'o bordes en vez de cubrir area. Mira el mapa de merodeo antes de tocar heuristica (§11).');
      }

      // R4 autojaula: escrituras propias en sus 8 vecinos y ninguna salida
      var propias = 0, w = game.worldWrites || [];
      for (var j = 0; j < w.length; j++) {
        if (w[j].agente !== nom) continue;
        if (Math.abs(w[j].x - a.x) <= 1 && Math.abs(w[j].z - a.z) <= 1) propias++;
      }
      if (propias >= 4 && R.libres === 0) {
        H.push('R4 · ' + nom + ': ' + propias + ' escrituras SUYAS en sus 8 vecinos y 0 vecinos ' +
               'pisables. Se esta encerrando el solo (§11).');
      }
    }

    var celdasCal = escriturasPorCelda(6);                    // R3
    for (var c = 0; c < celdasCal.length; c++) {
      var g = celdasCal[c];
      var aut = Object.keys(g.autores);
      if (aut.length >= 2) {
        H.push('R3 · celda [' + g.k + ']: ' + g.n + ' cambios de ' + aut.length + ' agentes (' +
               aut.join(', ') + '). Uno pone y otro quita: el atasco es ENTRE agentes, no dentro de ' +
               'uno (§21.2 — un peldano que mide "queda algo que picar" nunca termina).');
      }
    }

    var d = game.perfData;                                    // R7
    if (d) {
      var secs = (performance.now() - d.desde) / 1000;
      for (var fk in d.fases) {
        var pct = d.fases[fk].ms / 10 / Math.max(secs, 0.001);
        if (pct > 30) {
          H.push('R7 · la fase "' + fk + '" se lleva el ' + pct.toFixed(0) + '% de CPU. Mira el coste ' +
                 'antes que la heuristica (§18, §19): un agente que no llega a tiempo parece atascado.');
        }
      }
    }
    return H;
  }

  game.informe = function(opciones) {
    var o = opciones || {};
    var ticks = o.ticks || INFORME_TICKS;
    var max = o.max || INFORME_MAX;
    var todos = !!o.todos;
    var guardar = (o.guardar !== false);
    var filtro = (o.agentes && o.agentes.length) ? o.agentes : null;

    var ags = getAgentInstances();
    if (filtro) {
      ags = ags.filter(function(a) {
        return filtro.indexOf(a.id) >= 0 || filtro.indexOf(a.name) >= 0;
      });
    }

    var fichas = [];
    for (var i = 0; i < ags.length; i++) {
      // Se juzgan aqui tambien las pendientes que ya cumplieron plazo: un agente pausado o que dejo
      // de llamar a ejecutarTickEstandar tendria acciones sin veredicto y la tabla 3.3 mentiria.
      resolverAccionesPendientes(ags[i]);
      fichas.push({ a: ags[i], atasco: diagnosticarAtasco(ags[i]) });
    }
    var nAtascados = fichas.filter(function(f) { return !!f.atasco; }).length;

    var fecha = new Date();
    var cab = [];
    cab.push('# INFORME DE ATASCOS · VoxelForge');
    cab.push('');
    cab.push('## 0. PROCEDENCIA');
    cab.push('- generado: ' + fecha.toLocaleString());
    cab.push('- libreria: ' + VERSION_LIB + ' · huella ' + huellaLibreria() + '  (si no coincide con el fichero, la pestana no recargo)');
    cab.push('- mundo: ' + mc.dim.x + 'x' + mc.dim.y + 'x' + mc.dim.z +
             ' · ' + ags.length + ' agentes analizados · fps ' + (game.fps ? game.fps.toFixed(0) : 'n/d'));
    // Los segundos NO son ticks*0.2: dependen del tickMs de cada agente y de game.agentSpeed, que no
    // tiene tope. Con agentSpeed=100 la ventana real era ~0,8 s y el informe anunciaba 80.
    var vel = (typeof game.agentSpeed === 'number' && game.agentSpeed > 0) ? game.agentSpeed : 1;
    var tickMs = 200;
    for (var iv = 0; iv < ags.length; iv++) if (ags[iv].tickMs) { tickMs = ags[iv].tickMs; break; }
    var seg = ticks * (tickMs / vel) / 1000;
    cab.push('- ventana de analisis: ' + ticks + ' ticks (~' + (seg < 10 ? seg.toFixed(1) : Math.round(seg)) +
             ' s con tickMs ' + tickMs + ' y agentSpeed ' + vel + ')');
    var wr = game.worldWrites || [], porAutor = {}, lider = null;
    for (var iw = 0; iw < wr.length; iw++) {
      porAutor[wr[iw].agente] = (porAutor[wr[iw].agente] || 0) + 1;
      if (!lider || porAutor[wr[iw].agente] > porAutor[lider]) lider = wr[iw].agente;
    }
    if (lider && wr.length >= MAX_ESCRITURAS && porAutor[lider] > wr.length * 0.7) {
      cab.push('- **AVISO**: el anillo de escrituras esta lleno y el ' +
               Math.round(100 * porAutor[lider] / wr.length) + '% es de "' + lider + '". Las escrituras ' +
               'de los demas agentes se han desalojado: este informe NO puede hablar de ellos.');
    }
    cab.push('- anillos: traza 500 · escrituras ' + (game.worldWrites || []).length + '/' + MAX_ESCRITURAS +
             ' · cobertura 40 muestras. Lo anterior a eso NO esta en este informe.');
    if (typeof navigator !== 'undefined') cab.push('- navegador: ' + navigator.userAgent);

    // 1. veredicto
    cab.push('');
    cab.push('## 1. VEREDICTO — ' + nAtascados + ' de ' + fichas.length + ' atascados');
    if (!fichas.length) cab.push('No hay agentes vivos.');
    for (var v1 = 0; v1 < fichas.length; v1++) {
      var f = fichas[v1];
      cab.push('- **' + (f.a.name || f.a.id) + '** [' + f.a.x + ',' + f.a.y + ',' + f.a.z + '] — ' +
               (f.atasco ? (f.atasco.nivelAlert + ' · ' + f.atasco.motivo) : 'sin atasco medido'));
    }

    // 3. por agente (se construye antes que 2 porque las hipotesis leen sus resumenes)
    var piezas = [];
    var resumenes = [];
    for (var v2 = 0; v2 < fichas.length; v2++) {
      var fa = fichas[v2];
      if (!fa.atasco && !todos) { resumenes.push(null); continue; }
      resumenes.push(seccionAgente(fa.a, fa.atasco, ticks, piezas));
    }

    var H = hipotesis(fichas, resumenes);
    var hip = ['', '## 2. HIPOTESIS'];
    if (!H.length) hip.push('Ninguna regla dispara. Si aun asi se ve atasco, es algo que este informe no mide todavia.');
    for (var h = 0; h < H.length; h++) hip.push('- ' + H[h]);

    // 4. escrituras del mundo
    var esc = ['', '## 4. ESCRITURAS DEL MUNDO (celdas con >=3 cambios)'];
    var gr = escriturasPorCelda(3);
    if (!gr.length) esc.push('Ninguna celda cambio 3 veces o mas en el anillo. Nadie repone lo que otro pica.');
    else {
      esc.push('| celda | cambios | autores | secuencia |');
      esc.push('|---|---|---|---|');
      for (var g2 = 0; g2 < Math.min(gr.length, 20); g2++) {
        var G = gr[g2];
        var au = Object.keys(G.autores).map(function(k) { return k + ' x' + G.autores[k]; }).join(', ');
        esc.push('| [' + G.k + '] | ' + G.n + ' | ' + au + ' | ' + G.seq.join(' -> ') + ' |');
      }
      if (gr.length > 20) esc.push('_(' + (gr.length - 20) + ' celdas mas omitidas)_');
    }

    // 5. coste: solo si alguna fase pasa del 30 %
    var cos = [];
    var pd = game.perfData;
    if (pd) {
      var sc = (performance.now() - pd.desde) / 1000;
      var caras = [];
      for (var fk2 in pd.fases) {
        var pc = pd.fases[fk2].ms / 10 / Math.max(sc, 0.001);
        if (pc > 30) caras.push('- ' + fk2 + ': ' + pc.toFixed(0) + '% CPU · ' + pd.fases[fk2].llamadas + ' llamadas · peor ' + pd.fases[fk2].maxMs.toFixed(1) + ' ms');
      }
      if (caras.length) {
        cos.push(''); cos.push('## 5. COSTE');
        cos.push('Fases por encima del 30% de CPU (' + sc.toFixed(0) + ' s de muestreo):');
        cos = cos.concat(caras);
      }
    }

    // Presupuesto de tamano (§22): el informe tambien es un recurso acotado. Se sacrifica en orden
    // y CADA recorte se anuncia en la seccion 6; nada de truncar en silencio.
    var recortes = [];
    var orden = ['traza', 'heatmap', 'tickets', 'notas', 'sano'];
    var fuera = {};

    function montar(cortarCuerpoA) {
      var cuerpo = ['', '## 3. POR AGENTE'];
      var vacio = true;
      for (var p = 0; p < piezas.length; p++) {
        if (fuera[piezas[p].cat]) continue;
        cuerpo.push(piezas[p].txt);
        vacio = false;
      }
      if (vacio) {
        cuerpo.push(recortes.length
          ? '(sin detalle: recortado por presupuesto, ver seccion 6)'
          : '(sin detalle: no hay ningun agente atascado. Usa game.informe({todos:true}) para ver tambien los sanos.)');
      }
      var rec = ['', '## 6. RECORTES'];
      if (!recortes.length) rec.push('Ninguno: el informe entra entero en el presupuesto de ' + max + ' caracteres.');
      for (var r = 0; r < recortes.length; r++) rec.push('- ' + recortes[r]);
      var cuerpoTxt = cuerpo.join('\n');
      // El corte duro se hace SOBRE EL CUERPO, nunca sobre el final: la seccion 6 es la que dice que
      // se ha cortado, y cortarla a ella seria exactamente el truncado en silencio que §22 prohibe.
      if (cortarCuerpoA !== undefined && cuerpoTxt.length > cortarCuerpoA) {
        cuerpoTxt = cuerpoTxt.slice(0, Math.max(0, cortarCuerpoA)) + '\n…[cuerpo cortado]';
      }
      return cab.join('\n') + '\n' + hip.join('\n') + '\n' + cuerpoTxt + '\n' +
             esc.join('\n') + '\n' + cos.join('\n') + '\n' + rec.join('\n');
    }

    var txt = montar();
    for (var oi = 0; oi < orden.length && txt.length > max; oi++) {
      var cat = orden[oi];
      var bytes = 0, n = 0;
      for (var p2 = 0; p2 < piezas.length; p2++) {
        if (piezas[p2].cat === cat) { bytes += piezas[p2].txt.length; n++; }
      }
      if (!n) continue;
      fuera[cat] = true;
      recortes.push('omitido "' + cat + '" (' + n + ' bloques, ' + bytes + ' caracteres) para caber en ' + max + '.');
      txt = montar();
    }
    if (txt.length > max) {
      recortes.push('aun sobra: el cuerpo (seccion 3) va cortado. Repite acotando: game.informe({agentes:["<id>"]}).');
      var fijo = montar(0).length;
      txt = montar(Math.max(0, max - fijo));
    }

    game.informe.ultimo = txt;

    if (guardar && typeof fetch === 'function') {
      // El informe viaja como Markdown CRUDO dentro de un comentario de bloque, no como string
      // escapado: asi se lee tal cual en data/snippets/informe-atascos.json, sin \n por medio.
      var cuerpoSano = txt.replace(/\*\//g, '* /');
      var code = '/* ===== INFORME DE ATASCOS · ' + fecha.toLocaleString() + ' =====\n' +
                 cuerpoSano + '\n===== fin del informe ===== */\n' +
                 "console.log('Informe de atascos " + fecha.toLocaleString() +
                 ". Esta arriba en este comentario y en game.informe.ultimo.');\n";
      fetch('/api/snippets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: 'informe-atascos', name: 'Informe de atascos (generado)', code: code })
      }).then(function(r) {
        console.log(r.ok ? '📄 Informe guardado en data/snippets/informe-atascos.json (' + txt.length + ' caracteres).'
                         : '⚠️ El servidor rechazo el informe (' + r.status + '). Sigue en game.informe.ultimo.');
      }, function(err) {
        console.log('⚠️ No se pudo guardar el informe (' + err + '). Sigue en game.informe.ultimo y en el valor devuelto.');
      });
    }

    // El informe NO se vuelca entero a la consola: 30.000 caracteres son ~600 lineas y §22 vale
    // tambien para los diagnosticos. Va al fichero y al valor devuelto; aqui solo el resumen.
    console.log('📄 Informe de atascos · ' + nAtascados + '/' + fichas.length + ' agentes atascados · ' +
                H.length + ' hipotesis · ' + txt.length + ' caracteres' +
                (recortes.length ? ' · ' + recortes.length + ' recortes' : ''));
    console.log('   copy(game.informe.ultimo) para pegarlo, o data/snippets/informe-atascos.json en el servidor.');
    return txt;
  };
  game.informe.ultimo = '';

  function getCardinalName(dir) {
    if (!dir) return 'DESCONOCIDO';
    var dx = dir[0], dz = dir[1];
    if (dx === 1 && dz === 0) return 'ESTE (+X)';
    if (dx === -1 && dz === 0) return 'OESTE (-X)';
    if (dx === 0 && dz === 1) return 'SUR (+Z)';
    if (dx === 0 && dz === -1) return 'NORTE (-Z)';
    return '[' + dx + ',' + dz + ']';
  }

  function isCellValidExit(a, dx, dz) {
    if (!a.canWalk(dx, dz)) return false;
    var nx = a.x + dx, nz = a.z + dz;
    if (game.skills.isTrapPit(a, nx, nz)) return false;
    if (typeof a.getNote === 'function') {
      var ny = a.surfaceY(nx, nz);
      if (ny >= 0) {
        var noteObj = findExistingNoteInRadius(a, 'callejon sin salida', 2) || findExistingNoteInRadius(a, 'foso trampa', 2);
        if (noteObj && noteObj.note) {
          if (noteObj.note.indexOf(a.name + ':') >= 0) return false;
        }
      }
    }
    return true;
  }

  // ── LOG ACOTADO ─────────────────────────────────────────────────────────────────────────────
  // Por que existe: un agente atascado repite la MISMA decision ~10 veces por segundo (tickMs 90-200),
  // asi que una sola sesion dejo 1178 lineas identicas de [MINADO EMERGENCIA] en la consola. Un log de
  // ese tamano no se puede leer y ademas retiene las cadenas en memoria. logAgente(clave, msg) imprime
  // la primera aparicion de esa clave y luego, como mucho, una linea cada LOG_REPEAT_MS con cuantas
  // repeticiones se omitieron. La clave es del emisor, no del texto: asi tambien se acota un mensaje
  // que lleva contadores dentro y por tanto nunca se repite literal.
  var MAX_HISTORIAL = 200;         // toasts/tickets guardados por agente
  var MAX_HISTORIAL_GLOBAL = 500;  // game.toastHistory
  var LOG_REPEAT_MS = 10000;
  var MINADO_MAX_POR_CELDA = 8;    // veces que se pica desde la MISMA celda sin lograr abrir salida
  var logRepeat = {};
  function logAgente(clave, msg, msMin) {
    var now = performance.now();
    var espera = (msMin === undefined) ? LOG_REPEAT_MS : msMin;
    var e = logRepeat[clave];
    if (e) {
      e.n++;
      if (now - e.at < espera) return;
      var omitidas = e.n - 1;
      console.log(msg + (omitidas > 0
        ? '  (+' + omitidas + ' repeticiones omitidas en ' + ((now - e.at) / 1000).toFixed(0) + ' s)'
        : ''));
      e.at = now; e.n = 1;
      return;
    }
    logRepeat[clave] = { at: now, n: 1 };
    console.log(msg);
  }

  function emitAgentToast(a, msg, reason) {
    var now = performance.now();
    if (reason === 'escape' && a.vars.lastEscapeToastAt && (now - a.vars.lastEscapeToastAt < 10000)) {
      return;
    }
    if (reason === 'escape') a.vars.lastEscapeToastAt = now;

    var d = new Date();
    var timeStr = d.getHours() + ':' + String(d.getMinutes()).padStart(2,'0') + ':' + String(d.getSeconds()).padStart(2,'0');
    var logItem = '[' + timeStr + '] ' + a.name + ' en [' + a.x + ',' + a.y + ',' + a.z + '] (' + a.vars.visited.size + ' celdas 3D): ' + msg;

    a.vars.toastHistory = a.vars.toastHistory || [];
    a.vars.toastHistory.push(logItem);
    if (a.vars.toastHistory.length > MAX_HISTORIAL) a.vars.toastHistory.shift();
    game.toastHistory.push(logItem);
    if (game.toastHistory.length > MAX_HISTORIAL_GLOBAL) game.toastHistory.shift();

    var allowToast = (typeof game !== 'undefined' && game.showToastsEnabled === true);
    if (allowToast && typeof toast === 'function') toast(msg);
  }

  // ── PERFILADOR POR FASES ────────────────────────────────────────────────────────────────────────
  // Por que existe: cuando el Mundo pierde frames, ni las notas, ni el heatmap, ni la traza dicen
  // DONDE se va el tiempo — describen lo que el agente DECIDE, no lo que CUESTA. Esto mide reloj real
  // por fase del tick y guarda los peores ticks, que es lo unico que distingue "el agente esta atascado"
  // de "el agente esta quemando la CPU". game.perf() en F12.
  game.perfData = game.perfData || { fases: {}, peores: [], desde: performance.now(), ticks: 0 };

  function medir(fase, fn) {
    var t0 = performance.now();
    try { return fn(); }
    finally {
      var dt = performance.now() - t0;
      var f = game.perfData.fases[fase] || (game.perfData.fases[fase] = { llamadas: 0, ms: 0, maxMs: 0 });
      f.llamadas++; f.ms += dt; if (dt > f.maxMs) f.maxMs = dt;
      if (game.perfData._tickFases) {
        game.perfData._tickFases[fase] = (game.perfData._tickFases[fase] || 0) + dt;
      }
    }
  }
  game.skills_medir = medir;

  game.perf = function(topPeores) {
    var d = game.perfData;
    var secs = (performance.now() - d.desde) / 1000;
    var filas = [];
    for (var k in d.fases) {
      var f = d.fases[k];
      filas.push({ fase: k, llamadas: f.llamadas, 'ms total': +f.ms.toFixed(1),
                   'ms/s': +(f.ms / Math.max(secs, 0.001)).toFixed(1),
                   'ms/llamada': +(f.ms / Math.max(f.llamadas, 1)).toFixed(3),
                   'peor ms': +f.maxMs.toFixed(1),
                   '% CPU': +(f.ms / 10 / Math.max(secs, 0.001)).toFixed(1) });
    }
    filas.sort(function(x, y) { return y['ms total'] - x['ms total']; });
    console.log('=== COSTE POR FASE · ' + secs.toFixed(1) + ' s de muestreo · ' + d.ticks + ' ticks ===');
    console.table(filas);
    console.log('  "ms/s" = milisegundos de CPU gastados por segundo de reloj. 1000 ms/s = un nucleo saturado.');
    console.log('  "% CPU" por encima de ~30 en una fase = esa fase se esta comiendo los frames.');
    var peores = d.peores.slice().sort(function(x, y) { return y.ms - x.ms; }).slice(0, topPeores || 10);
    if (peores.length) {
      console.log('--- PEORES TICKS (los que producen el tiron visible) ---');
      console.table(peores.map(function(p) {
        return { hora: p.hora, tick: p.tick, agente: p.agente, 'ms del tick': +p.ms.toFixed(1),
                 'fase dominante': p.dominante, desglose: p.desglose };
      }));
    }
    return filas;
  };
  game.perf.reset = function() {
    game.perfData = { fases: {}, peores: [], desde: performance.now(), ticks: 0 };
    console.log('perfilador reiniciado');
  };

  game.skills = {
    // LIMITE DE DESNIVEL POR PASO (generico, cualquier agente): cuantos bloques puede subir/bajar de
    // UNA VEZ. Subir 1+1+1 por una escalera es legitimo; subir 2 de golpe no.
    //
    // POR QUE HACE FALTA MEDIRLO AQUI Y NO FIARSE DE app.js: mcAgentTarget (app.js:6292) mide el paso
    // contra a.y, y esta libreria reescribe a.y = surfaceY + 1 despues de cada tick — un bloque POR
    // ENCIMA de la cota de suelo que usa app.js (mcAgentMake pone a.y = mcSurfaceY, y mcSurfaceNear
    // devuelve tambien la Y del bloque solido). Esa unidad de mas corre la ventana entera: con climb:1
    // el agente subia de hecho 2 bloques de golpe (y bajaba uno menos de lo declarado). Aqui el
    // desnivel se mide suelo-contra-suelo, asi que no le afecta el desajuste.
    //
    // No se corrige a.y directamente porque la cota inflada esta metida en las claves de cobertura 3D
    // (a.vars.visited y el bodyY = cy + 1 de la BFS): cambiarla invalidaria la cobertura de todos los
    // agentes. Se arregla en la puerta de paso, que es lo que el usuario pide limitar.
    desnivelProhibido: function(a, dx, dz) {
      var climb = (a.climb === undefined || a.climb === null) ? 1 : a.climb;
      var drop = (a.drop === undefined || a.drop === null) ? 3 : a.drop;
      var cy = a.surfaceY(a.x, a.z);
      var ny = a.surfaceY(a.x + dx, a.z + dz);
      if (cy < 0 || ny < 0) return false;   // sin suelo: que decida app.js (abismo/borde)
      var diff = ny - cy;
      return diff > climb || diff < -drop;
    },

    local3x3Diagnostic: function(a) {
      var W = mc.dim.x, D = mc.dim.z;
      var curY = a.surfaceY(a.x, a.z);
      var climb = a.climb || 1, drop = a.drop || 3;
      var cardStr = getCardinalName(a.vars.dir);
      var lines = ['=== DIAGNÓSTICO LOCAL 3x3 (' + a.name + ' en [' + a.x + ',' + a.y + ',' + a.z + '], Cota Suelo Y=' + curY + ', Mirando: [' + a.vars.dir + '] ' + cardStr + ') ==='];
      var header = '  [Z\\X]       ';
      for (var dx = -1; dx <= 1; dx++) {
        var nx = a.x + dx;
        header += ('X=' + nx).padEnd(26);
      }
      lines.push(header);

      for (var dz = -1; dz <= 1; dz++) {
        var nz = a.z + dz;
        var row = (' Z=' + nz + ':   ').padEnd(12);
        for (var dx = -1; dx <= 1; dx++) {
          var nx = a.x + dx;
          if (dx === 0 && dz === 0) {
            var myMatId = curY >= 0 ? a.getBlock(a.x, curY, a.z) : 0;
            var myMat = getMatName(myMatId);
            row += ('Y=' + curY + ' (@AGENTE:' + myMat + ')').padEnd(26);
            continue;
          }
          if (nx < 1 || nx >= W - 1 || nz < 1 || nz >= D - 1) {
            row += 'BORDE_MAPA'.padEnd(26);
            continue;
          }
          var ny = a.surfaceY(nx, nz);
          if (ny < 0) {
            row += 'SIN_SUELO'.padEnd(26);
            continue;
          }
          var diff = ny - curY;
          var diffStr = (diff >= 0 ? '+' : '') + diff;
          var matId = a.getBlock(nx, ny, nz);
          var matName = getMatName(matId);
          var status = 'LIBRE';

          if (game.skills.isTrapPit(a, nx, nz)) {
            status = 'POZO_TRAMPA';
          } else if (diff > climb) {
            status = 'MURO_ALTO';
          } else if (diff < -drop) {
            status = 'CAIDA_ALTA';
          } else if (!a.canWalk(dx, dz)) {
            status = 'BLOQUEADO';
          }

          if (typeof a.getNote === 'function') {
            var noteObj = findExistingNoteInRadius(a, '', 1);
            if (noteObj && noteObj.note) {
              var note = noteObj.note;
              if (note.indexOf('callejon sin salida') >= 0) status = 'CALLEJÓN';
              else if (note.indexOf('foso trampa') >= 0) status = 'NOTA_FOSO';
              else if (note.indexOf('visitas a la cima') >= 0) status = 'NOTA_CIMA';
              else if (note.indexOf('escape de bucle') >= 0) status = 'NOTA_ESCAPE';
            }
          }

          row += ('Y=' + ny + ' (' + diffStr + ':' + status + ':' + matName + ')').padEnd(26);
        }
        lines.push(row);
      }
      return lines.join('\n');
    },

    getCurrentWalkable3D: function(a) {
      var W = mc.dim.x, D = mc.dim.z;
      var count = 0;
      for (var z = 1; z < D - 1; z++) {
        for (var x = 1; x < W - 1; x++) {
          if (a.surfaceY(x, z) >= 0) count++;
        }
      }
      return count || 1;
    },

    recordDeadEndVisit: function(a) {
      if (typeof a.getNote !== 'function') return;
      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return;

      var existingNoteObj = findExistingNoteInRadius(a, 'callejon sin salida', 2);
      var existingNote = existingNoteObj ? existingNoteObj.note : '';
      var notePos = existingNoteObj ? existingNoteObj.pos : [a.x, surfY, a.z];
      var deVisits = {};

      if (existingNote) {
        var lines = existingNote.split('\n');
        for (var i = 1; i < lines.length; i++) {
          var line = lines[i].trim();
          if (line.indexOf('Causa:') === 0 || line.indexOf('Cotas') === 0 || line.indexOf('Z-') === 0 || line.indexOf('Z=') === 0 || line.indexOf('Z+') === 0) {
            break;
          }
          var p = line.split(': ');
          if (p.length === 2) {
            var agentName = p[0].trim();
            if (agentName.indexOf('Z-') === 0 || agentName.indexOf('Z=') === 0 || agentName.indexOf('Z+') === 0 || agentName.indexOf('Causa') === 0) continue;
            var c = parseInt(p[1]);
            if (agentName && !isNaN(c)) deVisits[agentName] = c;
          }
        }
      }

      deVisits[a.name] = (deVisits[a.name] || 0) + 1;
      var outLines = ['callejon sin salida'];
      for (var nameKey in deVisits) {
        outLines.push(nameKey + ': ' + deVisits[nameKey] + ' veces');
      }
      var causeStr = 'Causa: Encierro en callejón sin salidas libres en abanico.';
      outLines.push(causeStr);
      outLines.push(get3x3HeightGridStr(a, notePos[0], notePos[2], notePos[1]));
      var noteText = outLines.join('\n');
      a.note(noteText, notePos);
      attachNoteTrace(a, notePos, 'callejon sin salida', causeStr, 'onTick() -> recordDeadEndVisit() -> a.note()');
    },

    recordTrapPitVisit: function(a, nx, nz) {
      if (typeof a.getNote !== 'function') return;
      var ny = a.surfaceY(nx, nz);
      if (ny < 0) return;

      var existingNoteObj = findExistingNoteInRadius(a, 'foso trampa', 2);
      var existingNote = existingNoteObj ? existingNoteObj.note : '';
      var notePos = existingNoteObj ? existingNoteObj.pos : [nx, ny, nz];
      var pitVisits = {};

      if (existingNote) {
        var lines = existingNote.split('\n');
        for (var i = 1; i < lines.length; i++) {
          var line = lines[i].trim();
          if (line.indexOf('Causa:') === 0 || line.indexOf('Cotas') === 0 || line.indexOf('Z-') === 0 || line.indexOf('Z=') === 0 || line.indexOf('Z+') === 0) {
            break;
          }
          var p = line.split(': ');
          if (p.length === 2) {
            var agentName = p[0].trim();
            if (agentName.indexOf('Z-') === 0 || agentName.indexOf('Z=') === 0 || agentName.indexOf('Z+') === 0 || agentName.indexOf('Causa') === 0) continue;
            var c = parseInt(p[1]);
            if (agentName && !isNaN(c)) pitVisits[agentName] = c;
          }
        }
      }

      pitVisits[a.name] = (pitVisits[a.name] || 0) + 1;
      var outLines = ['foso trampa'];
      for (var nameKey in pitVisits) {
        outLines.push(nameKey + ': ' + pitVisits[nameKey] + ' veces');
      }
      var causeStr = 'Causa: Caída a foso trampa local sin salidas laterales a la misma cota.';
      outLines.push(causeStr);
      outLines.push(get3x3HeightGridStr(a, notePos[0], notePos[2], notePos[1]));
      var noteText = outLines.join('\n');
      a.note(noteText, notePos);
      attachNoteTrace(a, notePos, 'foso trampa', causeStr, 'onTick() -> isTrapPit() -> recordTrapPitVisit() -> a.note()');
    },

    recordLoopEscapeVisit: function(a) {
      if (typeof a.getNote !== 'function') return;
      var now = performance.now();
      if (a.vars.lastEscapeNoteAt && (now - a.vars.lastEscapeNoteAt < 15000)) return;

      var existingNoteObj = findExistingNoteInRadius(a, 'escape de bucle', 3);
      if (existingNoteObj) return;

      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return;

      // (el contador de la nota es el literal '1 veces': mas arriba se sale si ya hay una nota de escape
      //  en radio 3, asi que una nota de escape nunca se reescribe ni acumula visitas de verdad)
      // OJO: esta nota NO la dispara detectar un bucle, sino agotarse la cuenta atras v.escapeSteps, que
      // arman 9 maniobras distintas (borde, frecuencia, ciclo, desatasco, desmonte de pino). Antes todas
      // escribian el mismo texto fijo de "oscilacion en micro-zona" y eso despistaba al leer las trazas:
      // una serpiente en linea recta sembraba una nota de bucle 5 ticks despues de una redireccion de
      // borde. Ahora cada maniobra deja su motivo en v.escapeMotivo y aqui se declara tal cual.
      var motivo = a.vars.escapeMotivo;
      var causeStr = motivo
        ? ('Causa: Fin de maniobra de escape (' + motivo + ').')
        : 'Causa: Fin de maniobra de escape (motivo no registrado).';
      var outLines = ['escape de bucle', a.name + ': 1 veces', causeStr, get3x3HeightGridStr(a, a.x, a.z, surfY)];
      var notePos = [a.x, surfY, a.z];
      a.note(outLines.join('\n'), notePos);
      a.vars.lastEscapeNoteAt = now;
      attachNoteTrace(a, notePos, 'escape de bucle', causeStr,
        'onTick() -> [' + (motivo || 'motivo no registrado') + '] -> recordLoopEscapeVisit() -> a.note()');
    },

    isTrapPit: function(a, nx, nz) {
      var W = mc.dim.x, D = mc.dim.z;
      if (nx < 1 || nx >= W - 1 || nz < 1 || nz >= D - 1) return true;
      var ny = a.surfaceY(nx, nz);
      if (ny < 0) return true;

      var noteObj = findExistingNoteInRadius(a, 'foso trampa', 2);
      if (noteObj && noteObj.note && noteObj.note.indexOf(a.name + ':') >= 0) {
        return true;
      }

      var cy = a.surfaceY(a.x, a.z);
      if (ny >= cy) return false;

      var climb = a.climb || 1;
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
      var exitCount = 0;

      for (var k = 0; k < 4; k++) {
        var tx = nx + dirs[k][0], tz = nz + dirs[k][1];
        if (tx >= 1 && tx < W - 1 && tz >= 1 && tz < D - 1) {
          var ty = a.surfaceY(tx, tz);
          if (ty >= 0 && (ty - ny) <= climb) {
            exitCount++;
          }
        }
      }

      if (exitCount === 0) {
        game.skills.recordTrapPitVisit(a, nx, nz);
        return true;
      }
      return false;
    },

    recordPeakVisit: function(a) {
      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return;

      var isLocalMax = true;
      var hasLowerNeighbor = false;
      var maxNeighborY = -1;
      for (var dz = -1; dz <= 1; dz++) {
        for (var dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dz === 0) continue;
          var ny = a.surfaceY(a.x + dx, a.z + dz);
          if (ny > surfY) { isLocalMax = false; break; }
          if (ny >= 0 && ny > maxNeighborY) maxNeighborY = ny;
          if (surfY > ny && ny >= 0) hasLowerNeighbor = true;
        }
        if (!isLocalMax) break;
      }
      var MIN_PROMINENCE = 3;
      var prominence = surfY - maxNeighborY;
      if (!isLocalMax || !hasLowerNeighbor || prominence < MIN_PROMINENCE) return;

      var existingNoteObj = findExistingNoteInRadius(a, 'visitas a la cima', 2) || findExistingNoteInRadius(a, 'pino de emergencia', 2);
      var existingNote = existingNoteObj ? existingNoteObj.note : '';
      var notePos = existingNoteObj ? existingNoteObj.pos : [a.x, surfY, a.z];
      var sk = a.vars.skills || {};

      var peakVisits = {};
      if (existingNote) {
        var lines = existingNote.split('\n');
        for (var i = 1; i < lines.length; i++) {
          var line = lines[i].trim();
          if (line.indexOf('Causa:') === 0 || line.indexOf('Cotas') === 0 || line.indexOf('Z-') === 0 || line.indexOf('Z=') === 0 || line.indexOf('Z+') === 0) {
            break;
          }
          var p = line.split(': ');
          if (p.length === 2) {
            var agentName = p[0].trim();
            if (agentName.indexOf('Z-') === 0 || agentName.indexOf('Z=') === 0 || agentName.indexOf('Z+') === 0 || agentName.indexOf('Causa') === 0) continue;
            var c = parseInt(p[1]);
            if (agentName && !isNaN(c)) peakVisits[agentName] = c;
          }
        }
      }

      // Antes se salia aqui si ya habia una visita: el contador se quedaba clavado en "1 veces" para todos
      // y no media nada. `visitaCimaUnaSolaVez` ya no congela la cuenta; lo que hace es que la cima no se
      // vuelva a elegir como DESTINO del BFS (ver colsVetadas).
      peakVisits[a.name] = (peakVisits[a.name] || 0) + 1;

      var outLines = ['visitas a la cima'];
      for (var nameKey in peakVisits) {
        outLines.push(nameKey + ': ' + peakVisits[nameKey] + ' veces');
      }
      var causeStr = 'Causa: cima local, ' + prominence + ' bloques por encima del vecino mas alto.';
      outLines.push(causeStr);
      // Las lineas de arriba son obligatorias: el parser de mas arriba lee los nombres entre la cabecera y
      // 'Causa:', asi que ni se tocan ni se reordenan. Lo de abajo es relleno explicativo, prescindible.
      var noteText = componerNota(a, outLines, [
        'Efecto: no se vuelve a elegir como DESTINO, pero se puede pasar por ella.',
        get3x3HeightGridStr(a, notePos[0], notePos[2], notePos[1])
      ]);
      a.note(noteText, notePos);
      attachNoteTrace(a, notePos, 'visitas a la cima', causeStr, 'onTick() -> recordPeakVisit() -> a.note()');
    },

    findNextStepToNearestUnvisited: function(a, excludeCols) {
      var W = mc.dim.x, D = mc.dim.z;
      var v = a.vars;
      var sk = v.skills || {};

      // MEMO DE "NO QUEDA FRONTERA ALCANZABLE". Cuando la serpiente ya ha cubierto el mapa, esta BFS
      // recorre los ~8.800 nodos enteros, no encuentra objetivo y devuelve null — y se repetia 1-2 veces
      // POR TICK, para siempre. visited solo CRECE, asi que si no hay frontera no puede reaparecer sola;
      // lo unico que puede devolverla es un salto tactico a otra region conectada (por eso el epoch) o
      // que alguien visite algo nuevo (por eso el tamano de visited). El rearme periodico es la red de
      // seguridad por si el terreno cambia bajo los pies del agente.
      var memo = v.bfsSinFrontera;
      if (memo && memo.epoca === (v.bfsEpoca || 0) && memo.visitedSize === v.visited.size
          && (a.stats.ticks - memo.tick) < 600) {
        v.bfsAhorradas = (v.bfsAhorradas || 0) + 1;
        return null;
      }
      var queue = [[a.x, a.z]];
      var qi = 0;   // puntero de cola: shift() es O(n) y con el mapa cubierto la cola llega a miles
      var visitedNodes = new Set();
      visitedNodes.add(a.x + ',' + a.z);
      var parentMap = {};
      var target = null;
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
      var climb = a.climb || 1, drop = a.drop || 3;

      // Columnas vetadas por nota (cima ya visitada / callejon sin salida / foso trampa).
      // ANTES esto se resolvia con findExistingNoteInRadius(a, '', 1) DENTRO del bucle, por cada vecino
      // de cada nodo: 27 llamadas a getNote por vecino (~944.000 por BFS con el mapa cubierto, 116 ms de
      // reloj) y ademas miraba el entorno del AGENTE, no la celda candidata — o sea que ni siquiera
      // vetaba lo que pretendia. El indice se construye ahora una sola vez desde mc.notes (unas pocas
      // entradas) y el veto pasa a ser una consulta O(1) sobre la celda correcta.
      var colsVetadas = new Set();
      var marcaAgente = a.name + ':';
      var todasNotas = (typeof mc !== 'undefined' && mc.notes) ? mc.notes : {};
      for (var nk in todasNotas) {
        var txt = todasNotas[nk];
        if (!txt || txt.indexOf(marcaAgente) < 0) continue;
        var veta = (sk.visitaCimaUnaSolaVez && txt.indexOf('visitas a la cima') >= 0)
                || txt.indexOf('callejon sin salida') >= 0
                || txt.indexOf('foso trampa') >= 0;
        if (!veta) continue;
        var pp = nk.split(',');
        if (pp.length === 3) colsVetadas.add(pp[0] + ',' + pp[2]);
      }

      while (qi < queue.length) {
        var curr = queue[qi++];
        var cx = curr[0], cz = curr[1];
        var cy = a.surfaceY(cx, cz);
        var bodyY = cy >= 0 ? cy + 1 : -1;

        if (cy >= 0 && !v.visited.has(cx + ',' + bodyY + ',' + cz)) {
          var isFloating = (a.y <= 17 && cy > 16)
          var vetadaComoDestino = colsVetadas.size > 0 && colsVetadas.has(cx + ',' + cz);
          if (!isFloating && !vetadaComoDestino && (!excludeCols || !excludeCols.has(cx + ',' + cz))) {
            target = [cx, cz];
            break;
          }
        }

        for (var i = 0; i < 4; i++) {
          var dx = dirs[i][0], dz = dirs[i][1];
          var nx = cx + dx, nz = cz + dz;
          if (nx >= 1 && nx < W - 1 && nz >= 1 && nz < D - 1) {
            if (cx === a.x && cz === a.z && !a.canWalk(dx, dz)) continue;
            if (cx === a.x && cz === a.z && excludeCols && excludeCols.has(nx + ',' + nz)) continue;
            if (cx === a.x && cz === a.z && game.skills.isTrapPit(a, nx, nz)) continue;

            var ny = a.surfaceY(nx, nz);
            var hDiff = ny - cy;
            if (ny >= 0 && hDiff <= climb && hDiff >= -drop) {
              var key = nx + ',' + nz;
              // El veto NO se aplica aqui, a proposito. Un `continue` en la expansion no dice "no vayas a
              // esa cima": borra la columna del grafo, asi que el BFS tampoco puede pasar POR ELLA hacia lo
              // que hay detras. Con una nota por cada pino plantado, la zona se quedaba sin rutas.
              if (!visitedNodes.has(key)) {
                visitedNodes.add(key);
                parentMap[key] = [cx, cz];
                queue.push([nx, nz]);
              }
            }
          }
        }
      }

      if (target) {
        var curr = target;
        while (curr[0] !== a.x || curr[1] !== a.z) {
          var pKey = curr[0] + ',' + curr[1];
          var parent = parentMap[pKey];
          if (!parent) break;
          if (parent[0] === a.x && parent[1] === a.z) {
            var step = [curr[0] - a.x, curr[1] - a.z];
            var backDir = [-v.dir[0], -v.dir[1]];
            if (step[0] === backDir[0] && step[1] === backDir[1]) {
              var ortho1 = [v.dir[1], -v.dir[0]], ortho2 = [-v.dir[1], v.dir[0]];
              if (isCellValidExit(a, ortho1[0], ortho1[1])) return ortho1;
              if (isCellValidExit(a, ortho2[0], ortho2[1])) return ortho2;
            }
            return step;
          }
          curr = parent;
        }
      }
      if (!target && !excludeCols) {
        v.bfsSinFrontera = { epoca: v.bfsEpoca || 0, visitedSize: v.visited.size, tick: a.stats.ticks };
      }
      return null;
    },

    // Vecinos pisables DE UNA CELDA CUALQUIERA (no del agente). a.canWalk(dx,dz) mide siempre desde
    // la posicion del agente, asi que usarlo dentro del barrido de saltoTactico daba el MISMO
    // openCount para los ~9000 candidatos: el de la celda donde el agente esta atrapado. Y esa celda
    // tiene 0 vecinos abiertos por definicion (por eso se pide rescate), luego openCount >= 2 no se
    // cumplia jamas y el salto devolvia false JUSTO cuando hacia falta.
    vecinosPisablesEn: function(a, x, y, z) {
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
      var climb = (a.climb === undefined) ? 1 : a.climb;
      var drop = (a.drop === undefined) ? 3 : a.drop;
      var n = 0;
      for (var k = 0; k < 4; k++) {
        var nx = x + dirs[k][0], nz = z + dirs[k][1];
        if (nx < 1 || nz < 1 || nx >= mc.dim.x - 1 || nz >= mc.dim.z - 1) continue;
        var ny = a.surfaceY(nx, nz);
        if (ny < 0) continue;
        // Mismo criterio que mcSurfaceNear: subir <= climb, bajar <= drop y aire sobre el suelo.
        if (ny - y > climb || y - ny > drop) continue;
        if (a.getBlock(nx, ny + 1, nz) !== 0) continue;
        n++;
      }
      return n;
    },

    saltoTactico: function(a, motivo) {
      var now = performance.now();
      if (a.vars.lastJumpAt && (now - a.vars.lastJumpAt < 3000)) return false;
      // Un barrido que NO encuentra destino cuesta lo mismo que uno que si (2 x 96x96 surfaceY + claves
      // de texto) y con el mapa cubierto es SIEMPRE el caso. Sin este freno se repetia en cada llamada:
      // el cooldown de arriba solo se armaba en el camino de exito.
      if (a.vars.lastJumpFailAt && (now - a.vars.lastJumpFailAt < 3000)) return false;
      anotarAccion(a, 'TACTICAL_JUMP');    // el INTENTO; un barrido que no elige destino tambien cuenta

      var W = mc.dim.x, D = mc.dim.z;
      var bestDist = 1e9, bestCell = null;
      var dirs = [[1,0],[0,1],[-1,0],[0,-1]];

      for (var z = 1; z < D - 1; z++) {
        for (var x = 1; x < W - 1; x++) {
          var y = a.surfaceY(x, z);
          if (y >= 0 && !a.vars.visited.has(x + ',' + (y + 1) + ',' + z)) {
            // La distancia se filtra ANTES de contar vecinos: contarlos es 4 barridos de columna y
            // aqui se evalua el mapa entero.
            var dist = Math.hypot(x - a.x, z - a.z);
            if (dist >= 5 && dist < bestDist && game.skills.vecinosPisablesEn(a, x, y, z) >= 2) {
              bestDist = dist; bestCell = { x: x, y: y, z: z };
            }
          }
        }
      }
      if (!bestCell) {
        for (var z = 1; z < D - 1; z++) {
          for (var x = 1; x < W - 1; x++) {
            var y = a.surfaceY(x, z);
            if (y >= 0 && !a.vars.visited.has(x + ',' + (y + 1) + ',' + z)) {
              var dist = Math.hypot(x - a.x, z - a.z);
              if (dist < bestDist && game.skills.vecinosPisablesEn(a, x, y, z) >= 2) {
                bestDist = dist; bestCell = { x: x, y: y, z: z };
              }
            }
          }
        }
      }

      if (bestCell) {
        logExecutionStep(a, 'TACTICAL_JUMP', 'Salto a [' + bestCell.x + ',' + (bestCell.y + 1) + ',' + bestCell.z + '] (' + (motivo || 'Escape') + ')');
        a.x = bestCell.x; a.y = bestCell.y + 1; a.z = bestCell.z;
        a.renderX = bestCell.x; a.renderY = bestCell.y + 1; a.renderZ = bestCell.z;
        a.stats.jumps = (a.stats.jumps || 0) + 1;
        a.vars.historial = [];
        a.vars.lastTicketAt = {};
        a.vars.lastCount = a.vars.visited.size;
        a.vars.lastJumpAt = now;
        a.vars.stepsWithoutNewCell = 0;
        a.vars.rescateEnPaso = 0;
        a.vars.freqBreakSinCelda = 0;

        // Modo serpiente: el teletransporte parte el cuerpo en dos, asi que se descarta y se vuelve a
        // formar detras de la cabeza en su nueva posicion.
        a.vars.cuerpo = [];
        a.vars.cuerpoSalientes = [];
        a.vars.ultimoPaso = null;
        emitAgentToast(a, '\u26A1 \u00A1' + a.name + ': Salto T\u00E1ctico a [' + bestCell.x + ',' + (bestCell.y + 1) + ',' + bestCell.z + '] (' + (motivo || 'Escape') + ')!', 'jump');
        logAgente('salto:' + a.id, '[SALTO TÁCTICO - ' + a.name + '] Tras ' + (motivo || 'encierro') + ', saltó a [' + bestCell.x + ',' + (bestCell.y + 1) + ',' + bestCell.z + ']');
        a.vars.bfsEpoca = (a.vars.bfsEpoca || 0) + 1;   // otra region conectada: invalida el memo de frontera
        a.vars.bfsSinFrontera = null;
        return true;
      }
      a.vars.lastJumpFailAt = now;
      return false;
    },

    // El pino es el hito estandar de esta libreria. `opts` solo cambia CUANTO mide el tronco y que
    // dice la nota: sin opts sale exactamente el pino de emergencia de siempre (tronco 2 + copa 3x3 +
    // cruz + punta), y con `alto` sale el mismo pino estirado, que es lo que se ve desde lejos.
    plantarPinoDeEmergencia: function(a, opts) {
      opts = opts || {};
      var surfY = a.surfaceY(a.x, a.z);
      if (surfY < 0) return null;
      var px = a.x, pz = a.z;
      var py = surfY + 1;

      var alto = Math.max(2, opts.alto || 2);
      var maxY = (mc.dim && mc.dim.y ? mc.dim.y : 40) - 1;
      if (py + alto + 2 > maxY) alto = Math.max(2, maxY - py - 2);   // la copa tiene que caber
      for (var i = 0; i < alto; i++) a.setBlock(px, py + i, pz, 'tronco');
      var copa = py + alto;

      for (var dx = -1; dx <= 1; dx++) {
        for (var dz = -1; dz <= 1; dz++) {
          a.setBlock(px + dx, copa, pz + dz, 'hierba');
        }
      }

      a.setBlock(px, copa + 1, pz, 'hierba');
      a.setBlock(px + 1, copa + 1, pz, 'hierba');
      a.setBlock(px - 1, copa + 1, pz, 'hierba');
      a.setBlock(px, copa + 1, pz + 1, 'hierba');
      a.setBlock(px, copa + 1, pz - 1, 'hierba');
      a.setBlock(px, copa + 2, pz, 'hierba');

      var causeStr = opts.causa || 'Causa: probé las 4 caras y ninguna abrió paso pisable.';
      var noteText = componerNota(a, [
        opts.titulo || 'pino de emergencia',
        opts.mensaje || (a.name + ': encerrado aquí, piqué y seguí sin salida. Dejo el pino como hito.')
      ], [
        causeStr,
        'Pos [' + px + ',' + surfY + ',' + pz + '] t=' + a.stats.ticks + ' sinAvance=' + (a.vars.stepsWithoutNewCell || 0),
        get3x3HeightGridStr(a, px, pz, surfY)
      ].concat(opts.extra || []));
      var notePos = [px, py, pz];
      a.note(noteText, notePos);
      emitAgentToast(a, opts.toast ||
        ('\u1F332 \u00A1' + a.name + ': Plant\u00F3 un pino c\u00F3nico piramidal 3D con nota justificativa!'), 'pino');
      attachNoteTrace(a, notePos, opts.titulo || 'pino de emergencia', causeStr,
                      opts.traza || 'minadoEmergencia() -> plantarPinoDeEmergencia() -> a.note()');
      return { x: px, y: py, z: pz, alto: alto + 3, nota: notePos };
    },

    // Celda de reaparicion al azar: suelo con al menos 2 vecinos pisables y lejos de donde murio. Se
    // sortea (no se barre el mapa entero como saltoTactico) para que dos muertes seguidas no manden
    // siempre al mismo sitio; si el sorteo falla, se barre como red de seguridad.
    celdaLibreAlAzar: function(a, lejosDe, minDist) {
      var W = mc.dim.x, D = mc.dim.z, m = (a.margin === undefined) ? 1 : a.margin;
      minDist = minDist || 10;
      var probar = function(x, z) {
        if (x < m + 1 || z < m + 1 || x >= W - m - 1 || z >= D - m - 1) return null;
        if (lejosDe && Math.hypot(x - lejosDe.x, z - lejosDe.z) < minDist) return null;
        var y = a.surfaceY(x, z);
        if (y < 0) return null;
        if (game.skills.vecinosPisablesEn(a, x, y, z) < 2) return null;
        return { x: x, y: y, z: z };
      };
      for (var i = 0; i < 300; i++) {
        var c = probar(Math.floor(Math.random() * W), Math.floor(Math.random() * D));
        if (c) return c;
      }
      for (var z2 = 0; z2 < D; z2++) {
        for (var x2 = 0; x2 < W; x2++) { var c2 = probar(x2, z2); if (c2) return c2; }
      }
      return null;
    },

    // MUERTE POR LA PROPIA COLA (§24). Se llama cuando la cabeza no tiene NINGUNA direccion viable que
    // no sea su propio cuerpo: un callejon de 1 de ancho del que la serpiente no sale jamas. Antes de
    // esto la valvula de escape dejaba pasar el paso prohibido, y el resultado era ping-pong entre dos
    // celdas para siempre (52.825 ticks, 0 celdas nuevas) que ademas NO se veia como atasco porque el
    // agente andaba en cada tick.
    serpienteMuerePorSuCola: function(a) {
      var px = a.x, pz = a.z, surfY = a.surfaceY(px, pz);
      var largo = (a.vars.cuerpo || []).length;
      // Lapida: el MISMO pino de la libreria, con el tronco estirado a 16 para que se vea desde lejos.
      var pino = game.skills.plantarPinoDeEmergencia(a, {
        alto: 16,
        titulo: 'serpiente muerta por su propia cola',
        mensaje: a.name + ': murio por su propia cola aqui. Se quedo sin salida que no fuera cuerpo propio.',
        causa: 'Causa: ninguna salida que no fuera su propio cuerpo (callejon de 1 de ancho).',
        extra: ['Largo del cuerpo al morir: ' + largo + ' segmentos.'],
        toast: '\u2620 ' + a.name + ': murio por su propia cola en [' + px + ',' + pz + ']',
        traza: 'a.walk() -> serpienteMuerePorSuCola() -> plantarPinoDeEmergencia({alto:16}) + reaparicion'
      });
      logExecutionStep(a, 'SNAKE_DEAD_BY_TAIL', 'Muerta por su propia cola en [' + px + ',' + surfY + ',' + pz + ']' +
                       (pino ? ' (pino de ' + pino.alto + ')' : ''));
      logAgente('cola:' + a.id, '[MUERTE POR COLA - ' + a.name + '] Sin salida en [' + px + ',' + surfY + ',' + pz + ']; pino + reaparicion');

      var destino = game.skills.celdaLibreAlAzar(a, { x: px, z: pz }, 10);
      if (!destino) return false;                       // mapa sin sitio: mejor dejarla donde esta
      a.x = destino.x; a.y = destino.y + 1; a.z = destino.z;
      a.renderX = destino.x; a.renderY = destino.y + 1; a.renderZ = destino.z;
      // Se renace entero: cuerpo, rumbo, historial y contadores de atasco. Si no, la serpiente llega a
      // su nueva casilla arrastrando el callejon anterior en las estructuras.
      a.vars.cuerpo = [];
      a.vars.cuerpoSalientes = [];
      a.vars.ultimoPaso = null;
      a.vars.historial = [];
      a.vars.recentVisits = [];
      a.vars.lastTicketAt = {};
      a.vars.stepsWithoutNewCell = 0;
      a.vars.rescateEnPaso = 0;
      a.vars.freqBreakSinCelda = 0;
      a.vars.bfsEpoca = (a.vars.bfsEpoca || 0) + 1;
      a.vars.bfsSinFrontera = null;
      a.stats.muertes = (a.stats.muertes || 0) + 1;
      logExecutionStep(a, 'SNAKE_RESPAWN', 'Reaparece en [' + a.x + ',' + a.y + ',' + a.z + ']');
      return true;
    },

    minadoEmergencia: function(a, dirs) {
      var W = mc.dim.x, D = mc.dim.z;
      var minedAny = false;

      // Presupuesto por celda. Sin el, "queda algo que picar" puede ser cierto para siempre: un
      // constructor vecino repone el mismo bloque que este pica y los dos se turnan indefinidamente
      // (1178 lineas identicas de log en 78,17,46, siempre la misma celda).
      var celda = a.x + ',' + a.y + ',' + a.z;
      if (a.vars.minadoCelda !== celda) { a.vars.minadoCelda = celda; a.vars.minadoIntentos = 0; }
      if ((a.vars.minadoIntentos || 0) >= MINADO_MAX_POR_CELDA) return false;
      anotarAccion(a, 'EMERGENCY_MINE');   // el INTENTO; el efecto lo juzga el informe (§21, §23)

      // El suelo del agente es a.y - 1 (a.y es la celda de sus pies, ver a.y = surfaceY + 1). NO vale
      // a.surfaceY(a.x, a.z): eso es el bloque solido mas ALTO de la columna, asi que bajo un techo o
      // dentro de lo que el propio agente ha construido se picaba metros por encima de su cabeza.
      var cy = a.y - 1;

      for (var m = 0; m < 4; m++) {
        var md = dirs[m];
        var mx = a.x + md[0], mz = a.z + md[1];
        if (mx >= 1 && mx < W - 1 && mz >= 1 && mz < D - 1 && !a.canWalk(md[0], md[1])) {
          // Un paso solo necesita dos celdas de aire: pies (cy+1) y cabeza (cy+2). Picar hasta la cima
          // de la columna vecina tiraba muros enteros en un solo tick.
          for (var yLevel = cy + 1; yLevel <= cy + 2; yLevel++) {
            var b = a.getBlock(mx, yLevel, mz);
            if (b !== 0) {
              a.setBlock(mx, yLevel, mz, 0);
              minedAny = true;
            }
          }
        }
      }

      // Picar NO es el exito: el exito es que DESPUES exista un vecino pisable. Sin esta comprobacion
      // devolvia true cada vez que quitaba un bloque, el llamador hacia `if (mined) return;` y la
      // cadena de rescate (rebobinado, salto tactico) no se alcanzaba nunca.
      var abrio = null;
      for (var q = 0; q < 4; q++) {
        if (a.canWalk(dirs[q][0], dirs[q][1])) { abrio = dirs[q]; break; }
      }

      if (minedAny && abrio) {
        a.vars.minadoIntentos = 0;
        logExecutionStep(a, 'EMERGENCY_MINE', 'Picó túnel de emergencia');
        a.stats.mined = (a.stats.mined || 0) + 1;
        a.vars.dir = abrio;
        a.vars.historial = [];
        emitAgentToast(a, '\u26CF\uFE0F \u00A1' + a.name + ': Pic\u00F3 t\u00FAnel de emergencia para abrir salida!', 'minado');
        logAgente('minado:' + a.id, '[MINADO EMERGENCIA] ' + a.name + ' picó bloques de muro en torno a ' + a.x + ',' + a.y + ',' + a.z + ' para abrir salida física.');
        return true;
      }
      if (minedAny) a.vars.minadoIntentos = (a.vars.minadoIntentos || 0) + 1;
      // El hito solo se deja si el picado NO abrio salida, y uno por sitio. Plantarlo al entrar (antes de
      // picar y sin condicion) levantaba un pino por CADA tick sin poder moverse (~10/s), cada uno encima
      // del anterior porque surfaceY ya devolvia la copa; y una columna con tronco encima deja de ser
      // pisable para todos (mcSurfaceNear exige aire sobre el suelo). El rescate construia la jaula.
      if (!findExistingNoteInRadius(a, 'pino de emergencia', 2)) {
        game.skills.plantarPinoDeEmergencia(a);
      }
      return false;
    },

    rebobinadoHistorico: function(a, backDir) {
      anotarAccion(a, 'REWIND');           // el INTENTO: con historial corto no hace nada y eso importa
      if (a.vars.historial.length >= 2) {
        a.vars.historial.pop();
        logExecutionStep(a, 'REWIND', 'Marcha atrás por historial');
        emitAgentToast(a, '\u1F504 ' + a.name + ': Rebobinando marcha atr\u00E1s por historial...', 'rebobinado');
        a.vars.dir = backDir;
      }
    },

    asciiMap: function(a) {
      var W = mc.dim.x, D = mc.dim.z;
      var lines = ['=== MAPA 2D INDIVIDUAL: Agente ' + a.name + ' (' + a.vars.visited.size + ' celdas 3D recorridas) Run ' + a.vars.runId + ' ==='];
      for (var z = 0; z < D; z++) {
        var row = '';
        for (var x = 0; x < W; x++) {
          if (x === a.x && z === a.z) row += '@';
          else {
            var found = false;
            for (var y = 0; y < mc.dim.y && !found; y++) {
              if (a.vars.visited.has(x + ',' + y + ',' + z)) found = true;
            }
            if (found) row += 'B';
            else if (a.surfaceY(x, z) >= 0) row += '.';
            else row += '#';
          }
        }
        lines.push(row);
      }
      lines.push('@=' + a.name + ' | B=Construido/Visitado | .=Superficie | #=Vacio');
      var out = lines.join('\n');
      console.log(out);
      return out;
    },

    showTickets: function(a) {
      if (!a.vars.ticketLog.length) { console.log('Sin tickets para ' + a.name + ' en esta run.'); return; }
      var act = [], inact = [];
      for (var k in a.vars.skills) {
        if (a.vars.skills[k]) act.push(k);
        else inact.push(k);
      }
      console.log('=== TICKETS Agente ' + a.name + ' Run ' + a.vars.runId + ' (' + a.vars.ticketLog.length + ') ===');
      console.log('=== HABILIDADES ACTIVAS: [' + (act.length ? act.join(', ') : 'Ninguna') + '] | INACTIVAS: [' + (inact.length ? inact.join(', ') : 'Ninguna') + '] ===');
      for (var i = 0; i < a.vars.ticketLog.length; i++) console.log(a.vars.ticketLog[i]);
    },

    emitTicket: function(a, motivo, uniqueRecent, yMin, yMax) {
      var v = a.vars;
      var now = performance.now();
      if (v.lastTicketAt[motivo] && (now - v.lastTicketAt[motivo] < 1500)) return;
      v.lastTicketAt[motivo] = now;

      v.tickets[motivo] = (v.tickets[motivo] || 0) + 1;
      var count = v.tickets[motivo];
      var totalTickets = 0;
      for (var m in v.tickets) totalTickets += v.tickets[m];

      var parts = [];
      for (var k in v.skills) parts.push(k + ':' + (v.skills[k] ? 'ON' : 'OFF'));
      var abilStr = ' Abil:[' + parts.join(',') + ']';

      var diag3x3 = game.skills.local3x3Diagnostic(a);
      var cardStr = getCardinalName(v.dir);

      var compacto = 'Run:' + v.runId
        + ' #' + count + '/' + totalTickets
        + ' Pos:[' + a.x + ',' + a.y + ',' + a.z + ']'
        + ' Dir:[' + v.dir + '] (' + cardStr + ')'
        + ' Y:[' + yMin + '-' + yMax + ']'
        + abilStr
        + ' Recientes:' + (uniqueRecent ? uniqueRecent.size : 0) + '/10'
        + ' Cobertura3D:' + v.visited.size + '/' + v.totalWalkable
        + ' Hist:[' + v.historial.slice(-5).join('->') + ']';

      var ticketStr = 'Ticket ' + v.runId + ' [' + motivo + '] ' + compacto;
      v.ticketLog.push(ticketStr + '\n' + diag3x3);
      if (v.ticketLog.length > MAX_HISTORIAL) v.ticketLog.shift();
      emitAgentToast(a, '\u1F916 ' + a.name + ': Ticket #' + count + ' (' + motivo + ')', 'ticket');
      // 1500 ms por motivo siguen siendo 40 tickets/minuto y cada uno arrastra el diagrama 3x3: es la
      // fuente principal de log gigante. En consola basta uno cada 15 s con el recuento; v.showTickets()
      // sigue teniendo la lista completa.
      logAgente('ticket:' + a.id + ':' + motivo, '[TICKET - ' + a.name + '] ' + ticketStr + '\n' + diag3x3, 15000);

      if (count >= 5) {
        a.stop('5x_' + motivo);
        v.show3x3();
        v.asciiMap();
        v.showTickets();
        if (typeof mc !== 'undefined') {
          if (mc.keys) { for (var k in mc.keys) mc.keys[k] = false; }
          if (mc.vel) { mc.vel[0] = 0; mc.vel[1] = 0; mc.vel[2] = 0; }
        }
        alert('TICKET FINAL (' + motivo + ') - Agente: ' + a.name + ' (Run ' + v.runId + ')'
          + '\n\nDetenido tras 5 tickets de tipo ' + motivo + '.'
          + '\nCobertura de este agente: ' + v.visited.size + '/' + v.totalWalkable + ' celdas 3D'
          + '\nBloques construidos: ' + (a.stats.built || 0)
          + '\nY-rango: ' + yMin + '-' + yMax
          + '\nHabilidades: ' + abilStr
          + '\n\n' + diag3x3
          + '\n\nTickets y mapa ASCII en consola F12.');
      }
    }
  };

  // Disparos seguidos de FREQ_BREAK sin descubrir columna nueva antes de que deje de ser preferente.
  // 12 es holgado a proposito: el umbral de la escalera es dinamico (8..30 segun terreno pisable), asi
  // que 12 disparos esteriles seguidos ya no se explican por "estoy terminando de barrer la zona".
  var FREQ_BREAK_MAX_SIN_CELDA = 12;

  // Criterio de peldano esteril del informe (§23): celdas nuevas por ejecucion juzgada. 0,05 deja
  // fuera con holgura a los peldanos utiles medidos (WALK 4,3 · BFS_FRONTIER 3,6 · BORDER_ESCAPE 1,6
  // · TURN_ORTHO1 0,18) y caza a los que solo remueven al agente (FREQ_BREAK 0,006 · TURN_ORTHO2
  // 0,005). La muestra minima evita acusar a un peldano que apenas se ha ejecutado.
  var TASA_ESTERIL = 0.05;
  var TASA_MIN_JUZGADAS = 20;

  // Contabilidad de un paso dado: columna visitada, historial, pathHistory y el contador de pasos
  // sin descubrir columna nueva. Devuelve true si la columna (x,z) era nueva.
  //
  // Vive aparte porque esto estaba escrito al final del tick y habia DOS ramas de escape
  // (LOOP_ESCAPE_2CELL y FREQ_BREAK) que caminan y hacen return antes de llegar hasta ahi: el agente
  // que mas escapaba era justo el que menos se anotaba. Medido en el mundo de juguete del pasillo de
  // 1 de ancho (test_contador_celda_nueva.js): 150 pasos dados, FREQ_BREAK en 120 ticks seguidos,
  // stepsWithoutNewCell congelado en 9 y visitedPlanar sin las columnas realmente pisadas. Con el
  // contador congelado la ESCALERA DE RESCATE entera era inalcanzable (no se disparaba nunca para
  // el unico agente que la necesitaba) y la frontera BFS trabajaba con celdas mal marcadas.
  function anotarPaso(a) {
    var v = a.vars;
    var pos3d = a.x + ',' + a.y + ',' + a.z;
    var posPlanar = a.x + ',' + a.z;
    var esColumnaNueva = !v.visitedPlanar.has(posPlanar);
    v.visited.add(pos3d);
    v.visitedPlanar.add(posPlanar);
    v.historial.push(pos3d);
    if (v.historial.length > 10) v.historial.shift();

    v.pathHistory = v.pathHistory || [];
    v.pathHistory.push(posPlanar);
    if (v.pathHistory.length > 300) v.pathHistory.shift();

    if (esColumnaNueva) {
      v.stepsWithoutNewCell = 0;
      v.rescateEnPaso = 0;
      v.freqBreakSinCelda = 0;
      v.cycleBreakMode = false;
    } else {
      v.stepsWithoutNewCell = (v.stepsWithoutNewCell || 0) + 1;
    }
    return esColumnaNueva;
  }

  game.defineStandardAgent = function(config) {
    // Cuerpo del tick estandar. Extraido de onTick para poder envolverlo en un try/finally (ver onTick).
    // Cierra sobre `config`, igual que cuando era un metodo del literal.
    function ejecutarTickEstandar(a) {
        var v = a.vars;
        var sk = v.skills;
        var dirs = [[1,0],[0,1],[-1,0],[0,-1]];
        var W = mc.dim.x, D = mc.dim.z;

        // Telemetria del informe (§23): se juzgan las acciones que ya cumplieron su plazo y se toma
        // una muestra de la curva de cobertura. Ambas son O(1) y mudas — no imprimen nada (§22).
        resolverAccionesPendientes(a);
        if (!v.progreso) v.progreso = [];
        if (v.progresoUltimoTick !== a.stats.ticks && (a.stats.ticks % 25) === 0) {
          v.progresoUltimoTick = a.stats.ticks;
          v.progreso.push({ tick: a.stats.ticks, celdas: v.visited ? v.visited.size : 0,
                            pasos: a.stats.steps, sinNueva: v.stepsWithoutNewCell || 0 });
          if (v.progreso.length > 40) v.progreso.shift();
        }

        var lastVisit = v.recentVisits[v.recentVisits.length - 1];
        if (!lastVisit || lastVisit.x !== a.x || lastVisit.z !== a.z) {
          v.recentVisits.push({ x: a.x, z: a.z, y: a.y, tick: a.stats.ticks });
          if (v.recentVisits.length > 3000) v.recentVisits.shift();
          v.ticksQuieto = 0;
        } else {
          // PUNTO CIEGO QUE ESTO TAPA: recentVisits solo apila cuando la celda CAMBIA, asi que un agente
          // completamente congelado depositaba UNA sola entrada y no lo veia ningun detector de merodeo
          // — justo el caso que mas falta hace detectar. Se cuenta aparte, sin tocar recentVisits (del
          // que dependen el mapa de calor, el escape por frecuencia y el pintado de lava).
          v.ticksQuieto = (v.ticksQuieto || 0) + 1;
        }

        var curCellVisits = (calculateAgentDensity(a, 50)[a.x + ',' + a.z] || 0);
        var surfYForLava = a.surfaceY(a.x, a.z);
        var peakNoteObjForLava = findExistingNoteInRadius(a, 'visitas a la cima', 2) || findExistingNoteInRadius(a, 'pino de emergencia', 2);
        var isElevatedStuck = (peakNoteObjForLava !== null) || ((surfYForLava >= 0) && (a.y > surfYForLava + 2) && (((v.stepsWithoutNewCell || 0) - (v.rescateEnPaso || 0)) >= 4));

        if (curCellVisits >= 10 || getHeatSymbol(curCellVisits) === '█' || isElevatedStuck) {
          if (surfYForLava >= 0) {
            var lavaId = a.matId('lava');
            // Presupuesto por celda. La comprobacion "aqui no hay lava" no basta: si alguien repone el
            // suelo —el propio cuerpo de la serpiente lo hacia— la marca se vuelve a pintar en cada
            // tick, y salieron 44.584 pintadas sobre DOS celdas (lava->tierra->lava->tierra x300 en el
            // anillo de escrituras, que se llevo entero). La marca se pone UNA vez por celda; si te la
            // borran, no se pelea.
            v.lavaCeldas = v.lavaCeldas || {};
            var kLava = a.x + ',' + a.z;
            if (lavaId && !v.lavaCeldas[kLava] && a.getBlock(a.x, surfYForLava, a.z) !== lavaId) {
              v.lavaCeldas[kLava] = 1;
              if (Object.keys(v.lavaCeldas).length > 300) v.lavaCeldas = {};   // cota de memoria
              a.enqueueBlock(a.x, surfYForLava, a.z, 'lava');
              logExecutionStep(a, 'LAVA_HOTSPOT', 'Pintó lava por atasco (' + curCellVisits + ' pasadas)');
