          if (detected) {
            v.cycleBreakMode = true;
            v.cyclePositions = detected.positions;
            v.cycleLength = detected.period;
            v.cycleBreakCountdown = detected.period + 5;
            logExecutionStep(a, 'CYCLE_DETECTED', 'Circuito de periodo ' + detected.period + ' detectado (' + detected.positions.size + ' celdas)');
          }
        }

        if (v.cycleBreakMode) {
          v.cycleBreakCountdown = (v.cycleBreakCountdown || 0) - 1;
          var exitFound = false;
          for (var cd = 0; cd < 4; cd++) {
            var cdx = dirs[cd][0], cdz = dirs[cd][1];
            if (a.canWalk(cdx, cdz)) {
              var cnk = (a.x + cdx) + ',' + (a.z + cdz);
              if (!v.cyclePositions.has(cnk)) {
                v.dir = [cdx, cdz];
                v.cycleBreakMode = false;
                v.escapeSteps = 3;
                v.escapeMotivo = 'salida natural de circuito';
                v.pathHistory = [];
                logExecutionStep(a, 'CYCLE_NATURAL_EXIT', 'Salida natural de circuito (periodo ' + v.cycleLength + ')');
                emitAgentToast(a, '\u1F504\u1F6AA ' + a.name + ': Circuito de ' + v.cycleLength + ' pasos. \u00A1Salida natural!', 'cycle_exit');
                game.skills.recordLoopEscapeVisit(a);
                exitFound = true;
                break;
              }
            }
          }
          if (!exitFound) {
            // Si no hay salida lateral natural, invertir dirección (U-Turn 180°) para romper el bucle rectangular
            v.dir = [-v.dir[0], -v.dir[1]];
            logExecutionStep(a, 'CYCLE_U_TURN', 'Giro U-Turn 180° para romper circuito cerrado');
          }
          if (v.cycleBreakCountdown <= 0) {
            v.cycleBreakMode = false;
            v.pathHistory = [];
          }
        }

        if (a.y > 17 && !v.cycleBreakMode && ((v.stepsWithoutNewCell || 0) - (v.rescateEnPaso || 0)) >= 3) {
          var lowestY = 999, lowestDir = null, lowestDx = 0, lowestDz = 0;
          for (var dd = 0; dd < 4; dd++) {
            var ddx = dirs[dd][0], ddz = dirs[dd][1];
            var dnx = a.x + ddx, dnz = a.z + ddz;
            if (dnx >= 1 && dnx < W - 1 && dnz >= 1 && dnz < D - 1) {
              var dny = a.surfaceY(dnx, dnz);
              if (dny >= 0 && dny < lowestY) {
                lowestY = dny; lowestDir = dirs[dd]; lowestDx = ddx; lowestDz = ddz;
              }
            }
          }
          var mySurf = a.surfaceY(a.x, a.z);
          if (lowestDir && lowestY < mySurf) {
            if (a.canWalk(lowestDx, lowestDz)) {
              v.dir = lowestDir;
              logExecutionStep(a, 'DESCENT', 'Descendiendo gradiente (' + a.y + ' -> ' + (lowestY+1) + ')');
            } else {
              var dropX = a.x + lowestDx, dropZ = a.z + lowestDz;
              var dropY = lowestY + 1;
              a.x = dropX; a.y = dropY; a.z = dropZ;
              a.renderX = dropX; a.renderY = dropY; a.renderZ = dropZ;
              v.stepsWithoutNewCell = 0;
              v.rescateEnPaso = 0;
              v.pathHistory = [];
              if (typeof a.note === 'function') {
                var towerSurfY = a.surfaceY(a.x, a.z);
                if (towerSurfY >= 0) {
                  var dropDist = mySurf - lowestY;
                  var noteLines = [
                    'salto desde torre',
                    a.name + ': 1 veces',
                    'Causa: Salto desde cima de torre (Y=' + (towerSurfY + 1) + ' -> Y=' + (lowestY + 1) + ', caida ' + dropDist + ' bloques)',
                    get3x3HeightGridStr(a, a.x, a.z, towerSurfY)
                  ];
                  var notePos = [a.x, towerSurfY, a.z];
                  a.note(noteLines.join('\n'), notePos);
                  attachNoteTrace(a, 'salto desde torre', notePos, 'salto desde la cima de la torre', 'recordTowerJumpVisit');
                }
              }
              logExecutionStep(a, 'EDGE_DROP', 'Salto al vacio desde Y=' + a.y + ' a Y=' + dropY + ' (caida de ' + (mySurf - lowestY) + ' bloques)');
              emitAgentToast(a, '\u1F3D7\uFE0F ' + a.name + ': \u00A1Salto desde la torre! Caida de ' + (mySurf - lowestY) + ' bloques', 'edge_drop');
              return;
            }
          }
        }

        var curNx = a.x + v.dir[0], curNz = a.z + v.dir[1];
        var curNy = a.surfaceY(curNx, curNz);
        var curBodyY = curNy >= 0 ? curNy + 1 : -1;
        var curIsUnvis = canFront && !v.visited.has(curNx + ',' + curBodyY + ',' + curNz);
        var inCorridor = !canOrtho1 && !canOrtho2;

        if (!curIsUnvis && v.escapeSteps <= 0) {
          if (v.postEscapeInertia > 0 && canFront) {
            // PRESERVAR INERCIA POST-ESCAPE
          } else if (inCorridor && canFront) {
            // Mantener inercia recta en pasillo estrecho
          } else {
            var bfsStep = medir('bfs', function(){ return game.skills.findNextStepToNearestUnvisited(a); });
            if (bfsStep) {
              v.dir = bfsStep;
              logExecutionStep(a, 'BFS_FRONTIER', 'Frontera BFS no visitada guiando avance');
            }
          }
        }

        var isNextPit = game.skills.isTrapPit(a, a.x + v.dir[0], a.z + v.dir[1]);
        var moved = false;
        if (!isNextPit) {
          moved = a.walk(v.dir[0], v.dir[1]);
        }

        if (!moved) {
          var bfsStepFallback = medir('bfs', function(){ return game.skills.findNextStepToNearestUnvisited(a); });
          if (bfsStepFallback) {
            v.dir = bfsStepFallback;
            if (!game.skills.isTrapPit(a, a.x + v.dir[0], a.z + v.dir[1])) {
              moved = a.walk(v.dir[0], v.dir[1]);
            }
          }
        }

        if (!moved) {
          for (var k = 0; k < 4; k++) {
            if (isCellValidExit(a, dirs[k][0], dirs[k][1])) {
              v.dir = dirs[k];
              moved = a.walk(v.dir[0], v.dir[1]);
              if (moved) break;
            }
          }
        }

        if (!moved) {
          for (var k = 0; k < 4; k++) {
            var dx = dirs[k][0], dz = dirs[k][1];
            if (a.canWalk(dx, dz) && !game.skills.isTrapPit(a, a.x + dx, a.z + dz)) {
              v.dir = dirs[k];
              moved = a.walk(v.dir[0], v.dir[1]);
              if (moved) break;
            }
          }
        }

        if (!moved) {
          var backDir = [-v.dir[0], -v.dir[1]];
          // Gateado como la otra llamada: sin esto, un agente con minadoEmergencia:false picaba igual.
          var mined = sk.minadoEmergencia ? game.skills.minadoEmergencia(a, dirs) : false;
          if (mined) return;

          if (sk.rebobinadoHistorico) {
            game.skills.rebobinadoHistorico(a, backDir);
            return;
          }

          if (sk.saltoTactico) {
            var jumped = medir('saltoTactico', function(){ return game.skills.saltoTactico(a, 'Rescate de Torre / Atasco'); });
            if (jumped) return;
          }

          var emergencyJumped = medir('saltoTactico', function(){ return game.skills.saltoTactico(a, 'Rescate Extremo Borde Mapa'); });
          if (emergencyJumped) return;

          game.skills.emitTicket(a, 'ATRAPADO_TOTAL', uniqueRecent, a.y, a.y);
          return;
        }

        if (moved) {
          logExecutionStep(a, 'WALK', 'Paso a [' + a.x + ',' + a.y + ',' + a.z + ']');
        }

        var postSurf = a.surfaceY(a.x, a.z);
        if (postSurf >= 0) {
          a.y = postSurf + 1;
          a.renderY = a.y;
        }

        var isNewPlanarCell = anotarPaso(a);

        if (!isNewPlanarCell) {
          var dynamicThreshold = calculateDynamicStuckThreshold(a);
          var peakNoteObj = findExistingNoteInRadius(a, 'visitas a la cima', 2) || findExistingNoteInRadius(a, 'pino de emergencia', 2);
          var isElevatedOnStructure = (peakNoteObj !== null) || ((postSurf >= 0) && (a.y > postSurf + 2)) || (postSurf > 16);
          var effectiveThreshold = isElevatedOnStructure ? 4 : dynamicThreshold;

          // stepsWithoutNewCell cuenta pasos SIN DESCUBRIR COLUMNA NUEVA y ya no se pone a cero
          // porque se lance una maniobra de rescate. Cuando se ponia, el contador media en realidad
          // "pasos desde el ultimo intento" y por construccion nunca pasaba del umbral: el informe de
          // atascos daba 18 para un agente que llevaba 975 pasos sin ganar una sola celda, y el
          // veredicto de game.stuck lo tapaba. Lo que se apunta al lanzar un rescate es rescateEnPaso,
          // y la escalera se dispara con la RESTA: vale exactamente lo que valia antes el
          // contador, asi que la cadencia de disparo no cambia; solo deja de mentir el contador.
          var pasosDesdeRescate = (v.stepsWithoutNewCell || 0) - (v.rescateEnPaso || 0);
          if (pasosDesdeRescate >= effectiveThreshold) {
            v.escapeMotivo = 'pasos sin descubrir celda nueva';

            // OJO con el orden. Antes esto hacia dos cosas mal:
            //  1) la nota se escribia AQUI, antes de intentar nada, asi que un simple giro que resolvia la
            //     situacion dejaba post-it igual. En llano abierto con el mapa ya explorado eso es ruido puro.
            //  2) las asignaciones de escapeMotivo estaban DESPUES del return, o sea que no se ejecutaban
            //     nunca: todo desvio ortogonal se etiquetaba con el motivo generico del padre y por eso las
            //     notas salian todas identicas.
            // Ahora: primero se intenta salir; el motivo se marca ANTES de irse; y si el desvio funciona la
            // nota la decide el fin de la cuenta atras (v.escapeSteps), que ya sabe si sirvio de algo.
            var o1 = [v.dir[1], -v.dir[0]], o2 = [-v.dir[1], v.dir[0]];
            if (isCellValidExit(a, o1[0], o1[1])) {
              v.escapeMotivo = 'desvio ortogonal por pasos sin celda nueva';
              v.dir = o1; v.escapeSteps = 5; v.rescateEnPaso = v.stepsWithoutNewCell; return;
            } else if (isCellValidExit(a, o2[0], o2[1])) {
              v.escapeMotivo = 'desvio ortogonal por pasos sin celda nueva';
              v.dir = o2; v.escapeSteps = 5; v.rescateEnPaso = v.stepsWithoutNewCell; return;
            }

            // Ningun desvio libre: esto ya no es saturacion, es estar encajonado. Aqui la nota SI informa.
            game.skills.recordLoopEscapeVisit(a);

            if (isElevatedOnStructure) {
              for (var bd = 0; bd < 4; bd++) {
                var bdx = dirs[bd][0], bdz = dirs[bd][1];
                var bnx = a.x + bdx, bnz = a.z + bdz;
                if (bnx >= 1 && bnx < W - 1 && bnz >= 1 && bnz < D - 1) {
                  var bny = a.surfaceY(bnx, bnz);
                  if (bny >= 0 && bny <= postSurf + 1) {
                    v.dir = dirs[bd];
                    v.escapeSteps = 5;
                    v.escapeMotivo = 'desmonte de estructura elevada';
                    v.rescateEnPaso = v.stepsWithoutNewCell;
                    logExecutionStep(a, 'DISMOUNT', 'Desmontó de estructura elevada');
                    emitAgentToast(a, '\u1F332 \u00A1' + a.name + ': Desmontando de la copa del pino hacia el suelo!', 'dismount');
                    a.walk(bdx, bdz);
                    return;
                  }
                }
              }
            }

            if (isElevatedOnStructure) {
              var groundY = -1, groundX = a.x, groundZ = a.z, bestDropDist = 1e9;
              var baseTerrainY = 14;
              for (var rad = 1; rad <= 10; rad++) {
                for (var rdz = -rad; rdz <= rad; rdz++) {
                  for (var rdx = -rad; rdx <= rad; rdx++) {
                    if (Math.abs(rdx) !== rad && Math.abs(rdz) !== rad) continue;
                    var rx = a.x + rdx, rz = a.z + rdz;
                    if (rx >= 1 && rx < W - 1 && rz >= 1 && rz < D - 1) {
                      var ry = a.surfaceY(rx, rz);
                      if (ry >= 0 && ry <= baseTerrainY + 2) {
                        var rdist = Math.abs(rdx) + Math.abs(rdz);
                        if (rdist < bestDropDist) { bestDropDist = rdist; groundY = ry; groundX = rx; groundZ = rz; }
                      }
                    }
                  }
                }
                if (groundY >= 0) break;
              }
              if (groundY >= 0) {
                a.x = groundX; a.y = groundY + 1; a.z = groundZ;
                a.renderX = groundX; a.renderY = groundY + 1; a.renderZ = groundZ;
                v.escapeSteps = 5; v.stepsWithoutNewCell = 0; v.rescateEnPaso = 0;
                v.escapeMotivo = 'salto al suelo desde estructura elevada';
                logExecutionStep(a, 'DISMOUNT', 'Salto al suelo desde estructura elevada a [' + groundX + ',' + (groundY+1) + ',' + groundZ + ']');
                emitAgentToast(a, '\u1F332\u2192\u1F3C3 ' + a.name + ': \u00A1Baj\u00F3 al suelo base!', 'dismount');
