                a.renderX = feX; a.renderY = feY + 1; a.renderZ = feZ;
                v.escapeSteps = 5; v.stepsWithoutNewCell = 0; v.rescateEnPaso = 0;
                v.escapeMotivo = 'teletransporte forzado al suelo';
                v.historial = [];
                logExecutionStep(a, 'FORCED_GROUND_ESCAPE', 'Teletransporte forzado al suelo [' + feX + ',' + (feY+1) + ',' + feZ + '] desde estructura elevada Y=' + postSurf);
                emitAgentToast(a, '\u26A1 ' + a.name + ': \u00A1Escape forzado al suelo desde Y=' + postSurf + '!', 'forced_escape');
