              }
            }
            v.rescateEnPaso = v.stepsWithoutNewCell;
          }
        }

        var yValues = v.historial.map(function(p) { return +p.split(',')[1]; });
        var yMin = Math.min.apply(null, yValues);
        var yMax = Math.max.apply(null, yValues);

        if (v.historial.length >= 10 && a.stats.ticks % 10 === 0) {
          if (uniqueRecent.size <= 3) {
            game.skills.emitTicket(a, 'BUCLE_DETECTADO', uniqueRecent, yMin, yMax);
          }
        }

        if (a.stats.ticks % 50 === 0) {
          var currentCount = v.visited.size;
          if (currentCount <= v.lastCount && uniqueRecent.size <= 2 && v.escapeSteps === 0 && v.postEscapeInertia === 0) {
            v.lastTicketCoverage = currentCount;
            game.skills.emitTicket(a, 'COBERTURA_ESTANCADA', uniqueRecent, yMin, yMax);
          }
          v.lastCount = currentCount;
        }
    }

    return game.defineAgent({
      id: config.id,
      name: config.name,
      block: config.block,
      margin: config.margin !== undefined ? config.margin : 1,
      climb: config.climb !== undefined ? config.climb : 1,   // desnivel maximo que SUBE de un paso
      drop: config.drop !== undefined ? config.drop : 3,      // desnivel maximo que BAJA de un paso
      passengers: config.passengers !== undefined ? config.passengers : true,
      tickMs: config.tickMs || 200,

      async onStart(a) {
        a.vars.skills = Object.assign({
          caminataAzotea: true,
          lookAheadPrevent: true,
          visitaCimaUnaSolaVez: true,
          minadoEmergencia: true,
          rebobinadoHistorico: false,
          saltoTactico: false,
          pintadoSincrono: false,
          construccionEnCapa: false,
          puertasMadera: false,
          modoSerpiente: false
        }, config.skills || {});

        a.vars.visited = new Set();
        a.vars.visitedPlanar = new Set();
        a.vars.lastCount = 0;
        a.vars.tickets = {};
        a.vars.ticketLog = [];
        a.vars.toastHistory = [];
        a.vars.recentVisits = [];
        a.vars.executionTrace = [];
        a.vars.historial = [];
        a.vars.dir = [1, 0];
        a.vars.lastTicketAt = {};
        a.vars.lastJumpAt = 0;
        a.vars.lastEscapeToastAt = 0;
        a.vars.escapeSteps = 0;
        a.vars.ticksQuieto = 0;
        a.vars.escapeMotivo = null;
        a.vars.postEscapeInertia = 0;
        a.vars.lastEscapeNoteAt = 0;
        a.vars.lastTicketCoverage = 0;
        a.vars.stepsWithoutNewCell = 0;
        a.vars.rescateEnPaso = 0;
        a.vars.freqBreakSinCelda = 0;

        // Modo serpiente (skill `modoSerpiente`). Se rellenan en el envoltorio de a.walk, mas abajo.
        a.vars.cuerpo = [];              // celdas del cuerpo; la 0 es la pegada a la cabeza
        a.vars.cuerpoSalientes = [];     // celdas que acaban de salir del cuerpo (cola a drenar por el snippet)
        a.vars.ultimoPaso = null;        // direccion del ultimo paso efectivo, para prohibir el giro de 180 grados

        // PROTECCIÓN ABSOLUTA DE OBSIDIANA: Ningún agente modifica ni repinta bloques de obsidiana
        if (typeof a.setBlock === 'function') {
