              return false;
            }
            var r = _origSetBlock.call(a, x, y, z, mat);
            var post = a.getBlock(x, y, z);          // solo se anota si el mundo CAMBIO de verdad
            if (post !== cur) anotarEscritura(a, Math.round(x), Math.round(y), Math.round(z), cur, post);
            return r;
          };
        }
        if (typeof a.paint === 'function') {
          var _origPaint = a.paint;
          a.paint = function(mat, x, z) {
            var surfY = a.surfaceY(x, z);
            if (surfY >= 0) {
              var obs1 = a.matId('obsidian'), obs2 = a.matId('obsidiana');
              var cur = a.getBlock(x, surfY, z);
              if ((obs1 && cur === obs1) || (obs2 && cur === obs2)) {
                return false;
              }
            }
            var r = _origPaint.call(a, mat, x, z);
            if (surfY >= 0) {
              var post = a.getBlock(x, surfY, z);
              if (post !== cur) anotarEscritura(a, Math.round(x), surfY, Math.round(z), cur, post);
            }
            return r;
          };
        }

        // Se envuelven a.canWalk y a.walk para que ninguna de las rutas del tick estandar (BFS, escapes
        // de bucle y de frecuencia, desatasco, desmonte de pino) pueda saltarse el limite de desnivel.
        // NO cubre el teletransporte (saltoTactico) ni el pino de emergencia: esos no pasan por walk.
        if (typeof a.canWalk === 'function') {
          var _origCanWalk = a.canWalk;
          a.canWalk = function(dx, dz) {
            if (game.skills.desnivelProhibido(a, dx, dz)) return false;
            return _origCanWalk.call(a, dx, dz);
          };
        }

        // MODO SERPIENTE (skill `modoSerpiente`): el agente arrastra un cuerpo de `largoSerpiente` celdas,
        // NO puede pisarlo y NO puede dar media vuelta sobre si mismo. Se implementa envolviendo a.walk
        // —igual que a.paint y a.setBlock aqui arriba— porque el tick estandar llama a walk desde media
        // docena de sitios (BFS, escapes de bucle y de frecuencia, desmonte de pino) y asi la regla vale
        // para todos sin tocar ninguno. La cola se actualiza AQUI, en el paso efectivo, no en el tick:
        // asi no se pierde ningun movimiento.
        if (typeof a.walk === 'function') {
          var _origWalk = a.walk;
          var largoSerpiente = Math.max(1, config.largoSerpiente || 10);
          var DIRS4 = [[1, 0], [0, 1], [-1, 0], [0, -1]];
          // Init defensivo: si algo reinicia a.vars por medio, el envoltorio se autorrepara en vez de
          // tumbar el tick entero del agente.
          var vars = function() {
            if (!a.vars.cuerpo) a.vars.cuerpo = [];
            if (!a.vars.cuerpoSalientes) a.vars.cuerpoSalientes = [];
            return a.vars;
          };
          var esCuerpo = function(x, z) {
            var c = vars().cuerpo;
            for (var i = 0; i < c.length; i++) if (c[i].x === x && c[i].z === z) return true;
            return false;
          };
          var prohibido = function(dx, dz) {
            var p = vars().ultimoPaso;
            if (p && dx === -p[0] && dz === -p[1]) return true;      // giro de 180 grados
            return esCuerpo(a.x + dx, a.z + dz);                     // morderse la cola
          };
          a.walk = function(dx, dz) {
            if (game.skills.desnivelProhibido(a, dx, dz)) {
              a.stats.blockedBySlope = (a.stats.blockedBySlope || 0) + 1;
              return false;
            }
            var sk = a.vars.skills;
            var modo = sk && sk.modoSerpiente;
            if (modo && prohibido(dx, dz)) {
              var salida = false;
              for (var i = 0; i < 4; i++) {
                var d = DIRS4[i];
                if ((d[0] !== dx || d[1] !== dz) && !prohibido(d[0], d[1]) && a.canWalk(d[0], d[1])) { salida = true; break; }
              }
              if (salida) { a.stats.blockedBySelf = (a.stats.blockedBySelf || 0) + 1; return false; }
              // Sin salida que no sea cuerpo propio: MUERE POR SU PROPIA COLA (§24). Antes esto era una
              // valvula que dejaba pasar el paso prohibido "para no congelar al agente", y lo que hacia
              // era un ping-pong entre dos celdas para siempre que ni siquiera contaba como atasco
              // (andaba en cada tick). Ahora deja lapida y reaparece.
              game.skills.serpienteMuerePorSuCola(a);
              return false;
            }
            var antesX = a.x, antesZ = a.z;
            var ok = _origWalk.call(a, dx, dz);
            if (modo && ok && (a.x !== antesX || a.z !== antesZ)) {
              vars().ultimoPaso = [a.x - antesX, a.z - antesZ];
              vars().cuerpo.unshift({ x: antesX, z: antesZ });        // la celda que se abandona pasa a ser cuerpo
              while (a.vars.cuerpo.length > largoSerpiente) a.vars.cuerpoSalientes.push(a.vars.cuerpo.pop());
            }
            return ok;
          };
        }

        a.enqueueBlock = function(x, y, z, block) {
          a.vars.buildQueue = a.vars.buildQueue || [];
          a.vars.buildQueue.push({ action: 'setBlock', x: x, y: y, z: z, block: block });
          if (!a.vars.isBuildingAsync) processAgentBuildQueue(a);
        };
        a.enqueuePaint = function(x, z, block) {
          a.vars.buildQueue = a.vars.buildQueue || [];
          a.vars.buildQueue.push({ action: 'paint', x: x, z: z, block: block });
          if (!a.vars.isBuildingAsync) processAgentBuildQueue(a);
        };

        logExecutionStep(a, 'START', 'Agente iniciado en [' + a.x + ',' + a.y + ',' + a.z + ']');

        if (typeof game.addMaterial === 'function') {
          if (config.block) await game.addMaterial(config.block);
          if (config.paintBlock) await game.addMaterial(config.paintBlock);
          if (config.buildBlock) await game.addMaterial(config.buildBlock);
          if (config.triggerFloor) await game.addMaterial(config.triggerFloor);
          await game.addMaterial('obsidiana');
          await game.addMaterial('obsidian');
          await game.addMaterial('red_concrete');
          await game.addMaterial('tronco');
          await game.addMaterial('hierba');
        }

        if (typeof mcMat2id !== 'undefined') mcMat2id = {};
        a._mat = {};

        a.vars.recentVisits.push({ x: a.x, z: a.z, y: a.y, tick: a.stats.ticks });
        a.vars.totalWalkable = game.skills.getCurrentWalkable3D(a);

        if (config.paintBlock) a.vars.paintId = a.matId(config.paintBlock);
        if (config.triggerFloor) a.vars.triggerId = a.matId(config.triggerFloor);
        if (config.buildBlock) a.vars.buildId = a.matId(config.buildBlock);

        a.stats.built = 0;
        a.stats.mined = 0;
        a.stats.jumps = 0;

        var d = new Date();
        a.vars.runId = d.getHours() + ':' + String(d.getMinutes()).padStart(2,'0') + ':' + String(d.getSeconds()).padStart(2,'0');

        a.vars.show3x3 = function() { var diag = game.skills.local3x3Diagnostic(a); console.log(diag); return diag; };
        a.vars.asciiMap = function() { return game.skills.asciiMap(a); };
        a.vars.showTickets = function() { return game.skills.showTickets(a); };
        a.vars.showToastHistory = function() {
          console.log('=== HISTORIAL DE TOASTS (' + a.name + ' - Total ' + a.vars.toastHistory.length + ') ===');
          for (var i = 0; i < a.vars.toastHistory.length; i++) console.log(a.vars.toastHistory[i]);
          return a.vars.toastHistory;
        };
        a.vars.showHeatmap = function(windowTicks) {
          var W = mc.dim.x, D = mc.dim.z;
          var grid = calculateAgentDensity(a, windowTicks);
          var modeTitle = windowTicks ? ('Últimos ' + windowTicks + ' Ticks / ~' + Math.round(windowTicks*0.2) + 's') : 'Acumulado Total de Pasadas Físicas';
          var lines = ['=== REJILLA 2D DEL MAPA DE CALOR DE OSCILACIÓN: ' + a.name + ' (' + modeTitle + ') ==='];
          var header = '  [Z\\X] ';
          for (var x = 0; x < W; x++) header += (x % 10);
          lines.push(header);
          for (var z = 0; z < D; z++) {
            var row = (' Z=' + String(z).padStart(2, '0') + ': ').substring(0, 8);
            for (var x = 0; x < W; x++) {
              if (x === a.x && z === a.z) {
                row += '@';
              } else {
                var count = grid[x + ',' + z] || 0;
                row += getHeatSymbol(count);
              }
            }
            lines.push(row);
          }
          lines.push('LEYENDA: . = Tránsito Fluido (1-2) | ░ = Templado (3-5) | ▒ = Oscilación (6-9) | █ = 🔥 ATASCO CRÍTICO (10+) | @ = Agente (' + a.x + ',' + a.z + ')');
          var out = lines.join('\n');
          console.log(out);
          return out;
        };
        a.vars.tacticalJump = function(motivo) { return game.skills.saltoTactico(a, motivo); };
        a.vars.traceNote = function(x, y, z) {
          var key = (x !== undefined && y !== undefined && z !== undefined) ? (x + ',' + y + ',' + z) : (a.x + ',' + a.y + ',' + a.z);
          return game.traceNote(key);
        };

        if (typeof config.onStart === 'function') {
          var userStart = config.onStart(a);
          if (userStart && typeof userStart.then === 'function') await userStart;
        }

        console.log('[F12] ' + a.name + ' (BFS Frontier Optimal) iniciado. Total caminable inicial: ' + a.vars.totalWalkable + ' celdas 3D. Run ' + a.vars.runId);
        console.log('  .vars.show3x3()         --> Diagnóstico 3x3 Local');
        console.log('  .vars.asciiMap()        --> Mapa 2D');
        console.log('  .vars.showTickets()     --> Historial de tickets');
        console.log('  .vars.showToastHistory()--> Historial de toasts emitidos');
        console.log('  .vars.showHeatmap()     --> Rejilla 2D del Mapa de Calor de Oscilación');
        console.log('  .vars.traceNote(x,y,z)  --> TRAZA COMPLETA DE EJECUCIÓN DE NOTA DESDE EL INICIO');
        console.log('  game.agents()           --> Tabla general');
        console.log('  game.stuck()            --> DIAGNÓSTICO DIRECTO DE AGENTES EN ATASCO ACTIVO');
        console.log('  game.toastLog()         --> Registro global de toasts');
        console.log('  game.heatmap()          --> Rejilla 2D del Mapa de Calor Global');
        console.log('  game.traceNote(x,y,z)   --> Inspeccionar traza histórica completa de una nota');
        console.log('  game.informe()          --> INFORME DE ATASCOS completo (fichero + string). §23');
      },

      onTick(a) {
        // El cuerpo del tick estandar tiene ~12 `return` tempranos, y tres de ellos salen JUSTO DESPUES
        // de un a.walk() con exito (escape de oscilacion, escape por frecuencia y desmontar del pino).
        // Llamar a config.onTick desde dentro del cuerpo hacia que el hook del snippet se perdiera en
        // esos caminos: el agente se movia y su onTick no se enteraba, sin poder recuperarse nunca.
        // El try/finally garantiza que config.onTick se llama SIEMPRE, una vez por tick, aunque el tick
        // estandar salga antes de tiempo o lance.
        // El perfilador envuelve el tick ENTERO (no solo el tick estandar) para que el desglose por
        // fases sume lo mismo que el coste real: si 'tick' es mucho mayor que la suma de las fases
        // medidas, el tiempo se va en codigo aun sin instrumentar, y eso tambien es informacion.
        game.perfData._tickFases = {};
        var _t0 = performance.now();
        try {
          try { ejecutarTickEstandar(a); }
          finally { if (typeof config.onTick === 'function') medir('onTick', function(){ config.onTick(a); }); }
        } finally {
          var _dt = performance.now() - _t0;
          var pd = game.perfData;
          pd.ticks++;
          var ft = pd.fases['tick'] || (pd.fases['tick'] = { llamadas: 0, ms: 0, maxMs: 0 });
          ft.llamadas++; ft.ms += _dt; if (_dt > ft.maxMs) ft.maxMs = _dt;
          if (_dt > 30) {   // solo los ticks que de verdad se notan como tiron
            var desg = [], tf = pd._tickFases, dom = '-', domMs = 0;
            for (var fk in tf) {
              desg.push(fk + ' ' + tf[fk].toFixed(1) + 'ms');
              if (tf[fk] > domMs) { domMs = tf[fk]; dom = fk; }
            }
            if (domMs < _dt * 0.5) dom = 'sin instrumentar (' + (_dt - domMs).toFixed(0) + 'ms fuera de fases)';
            pd.peores.push({ hora: new Date().toLocaleTimeString('es-ES'), tick: a.stats.ticks,
                             agente: a.id, ms: _dt, dominante: dom, desglose: desg.join(' · ') });
            if (pd.peores.length > 60) pd.peores.shift();
          }
          pd._tickFases = null;
        }
      }
    });
  };

  // ============================================================================================
  // CUERPOS DE AGENTE: escala, vuelo y cuerpo de ESTRUCTURA
  // ============================================================================================
  // app.js dibuja SIEMPRE el mismo cuerpo: un cubo 1x1x1 sacado del atlas del terreno, apoyado en
  // renderY+1 (mcAgentMesh). No admite escala, ni altura libre, ni voxeles finos.
  //
  // Esto NO se arregla tocando app.js (REGLAS §0): los snippets corren en ambito global, asi que
  // alcanzan las funciones globales del framework y se pueden ENVOLVER. Aqui se envuelven dos:
  //
  //   mcAgentMesh(a)  -> lo llama mcAgentsSmoothUpdate en CADA frame, justo despues de fijar
  //                      a.renderY pegandolo al suelo. Es el sitio exacto para (1) devolver la
  //                      altura de vuelo y (2) construir un cubo a escala en vez del de 1x1x1.
  //   mcRender()      -> se le encadena una pasada propia al final (con el depth buffer del frame
  //                      todavia puesto) para dibujar cuerpos de ESTRUCTURA, que usan otros shaders
  //                      (mc.structProg / mc.stexProg) que el bucle de agentes de app.js no toca.
  //
  // POR QUE NO se meten en mc.structures, que ya se dibujan solas: mcSerialize() las guarda en el
  // JSON del mundo. La nube quedaria ESTAMPADA para siempre donde pillase el autoguardado.
  //
  // Sirve a cualquier agente, no solo a la nube -> vive en la libreria (REGLAS §0, prioridad 1).
  //
  //   game.skills.cuerpo(a, { bloque:'snow', escala:3, altura:26 });
  //   await game.skills.cuerpo(a, { estructura:'hab:nube', escala:2, altura:26 });
  //
  // LIMITACION CONOCIDA: la COLISION del agente sigue siendo el cubo 1x1x1 de app.js (mcCollides
  // le da un AABB fijo en [renderY+1, renderY+2)). Un cuerpo a escala 3 se ve grande pero se choca
  // pequeno. Cambiarlo si exige app.js.

  var cuerposInstalado = false;

  function cuerpoDe(a) { return a && a.vars ? a.vars._cuerpo : null; }

  // Cubo del atlas a escala k, centrado en la celda del agente y apoyado en su misma cota.
  // Calca el mcAgentMesh de app.js (mismo layout x,y,z,u,v,shade y mismo VBO a.vbo) para que la
  // pasada de agentes del framework lo dibuje sin enterarse de nada.
  function mallaCuboEscalado(a, c) {
    var gl = mc.gl; if (!gl) return;
    var rects = mc.palette[a.blockId];
    if (!rects && mc.palette.length > 1) { a.blockId = 1; rects = mc.palette[1]; }
    if (!rects) { a.count = 0; return; }
    var k = c.escala;
    var rx = a.renderX !== undefined ? a.renderX : a.x;
    var ry = a.renderY !== undefined ? a.renderY : a.y;
    var rz = a.renderZ !== undefined ? a.renderZ : a.z;
    var ox = rx + 0.5 - k / 2, oy = ry + 1, oz = rz + 0.5 - k / 2;
    var verts = [], ord = [0, 1, 2, 0, 2, 3];
    for (var f = 0; f < 6; f++) {
      var F = MC_FACES[f], r = rects[F.tex], C = F.corners;
      var uv = [[r.u0, r.v0], [r.u1, r.v0], [r.u1, r.v1], [r.u0, r.v1]];
      for (var i = 0; i < 6; i++) {
        var q = ord[i], cc = C[q];
        verts.push(ox + cc[0] * k, oy + cc[1] * k, oz + cc[2] * k, uv[q][0], uv[q][1], F.s);
      }
    }
    if (!a.vbo) a.vbo = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, a.vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(verts), gl.DYNAMIC_DRAW);
    a.count = 36;
  }

  // Malla fina de una estructura, UNA sola vez y en coordenadas LOCALES (el origen de la estructura
  // en 0,0,0). No se re-sube al moverse: la pasada de dibujo premultiplica la vista por una
  // traslacion, que es gratis. Sin hornear luz: el cuerpo va a pleno brillo, como el cubo de app.js.
  function construirMallaEstructura(a, c) {
    var gl = mc.gl;
    if (!gl) return Promise.resolve(null);
    return mcStructGeom(c.estructura, 0).then(function (geom) {
      var k = c.escala;
      function sube(src, count, stride) {
        if (!count) return null;
        var d = new Float32Array(src.length);
        for (var i = 0; i < count; i++) {
          var b = i * stride;
          d[b] = src[b] * k; d[b + 1] = src[b + 1] * k; d[b + 2] = src[b + 2] * k;
          for (var j = 3; j < stride; j++) d[b + j] = src[b + j];
        }
        var vbo = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
        gl.bufferData(gl.ARRAY_BUFFER, d, gl.STATIC_DRAW);
        return vbo;
      }
      return {
        colVbo: sube(geom.colLocal, geom.colCount, 9), colCount: geom.colCount,
        alphaVbo: sube(geom.alphaLocal, geom.alphaCount, 9), alphaCount: geom.alphaCount,
        texVbo: sube(geom.texLocal, geom.texCount, 10), texCount: geom.texCount,
        ext: { x: geom.ext.x * k, y: geom.ext.y * k, z: geom.ext.z * k }
      };
    });
  }

  function liberarMallaEstructura(m) {
    if (!m || !mc.gl) return;
    if (m.colVbo) mc.gl.deleteBuffer(m.colVbo);
    if (m.alphaVbo) mc.gl.deleteBuffer(m.alphaVbo);
    if (m.texVbo) mc.gl.deleteBuffer(m.texVbo);
  }

  // Pasada propia, encadenada al final de mcRender. Recorre solo los agentes con cuerpo de
  // estructura (coste 0 si no hay ninguno) y los coloca con uView = vista * traslacion.
  function dibujarCuerposEstructura() {
    var gl = mc.gl;
    if (!gl || !mc.agents || !mc.agents.size || !mc.structProg) return;
    var pendientes = [];
    mc.agents.forEach(function (a) {
      var c = cuerpoDe(a);
      if (c && c.malla && a.state !== 'stopped') pendientes.push(a);
    });
    if (!pendientes.length) return;
    var pj = mcProjMatrix(), view = mcViewMatrix();
    var SL = mc.structLoc, sstr = 9 * 4;
    function vista(a, c) { return mat4.mul(view, modelo(a, c)); }
    gl.useProgram(mc.structProg);
    gl.uniformMatrix4fv(SL.uProj, false, pj.m);
    gl.uniform3f(SL.uSky, MC_SKY[0], MC_SKY[1], MC_SKY[2]);
    gl.uniform1f(SL.uFogNear, pj.far * 0.55); gl.uniform1f(SL.uFogFar, pj.far * 0.98);
    mcAttribs([SL.aPos, SL.aColor, SL.aShade, SL.aEmit, SL.aAlpha]);
    var i, a, c;
    for (i = 0; i < pendientes.length; i++) {          // 1) voxeles opacos
      a = pendientes[i]; c = cuerpoDe(a);
      if (!c.malla.colCount) continue;
      gl.uniformMatrix4fv(SL.uView, false, vista(a, c));
      gl.bindBuffer(gl.ARRAY_BUFFER, c.malla.colVbo);
      mcStructAttrib(SL, sstr);
      gl.drawArrays(gl.TRIANGLES, 0, c.malla.colCount);
    }
    var hayAlpha = false;
    for (i = 0; i < pendientes.length; i++) if (cuerpoDe(pendientes[i]).malla.alphaCount) hayAlpha = true;
    if (hayAlpha) {                                     // 2) voxeles translucidos (una nube de verdad)
      gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA); gl.depthMask(false);
      for (i = 0; i < pendientes.length; i++) {
        a = pendientes[i]; c = cuerpoDe(a);
        if (!c.malla.alphaCount) continue;
        gl.uniformMatrix4fv(SL.uView, false, vista(a, c));
        gl.bindBuffer(gl.ARRAY_BUFFER, c.malla.alphaVbo);
        mcStructAttrib(SL, sstr);
        gl.drawArrays(gl.TRIANGLES, 0, c.malla.alphaCount);
      }
      gl.depthMask(true); gl.disable(gl.BLEND);
    }
    // 3) voxeles `tex:` (solo si su clave llego al atlas de estructuras; si no, mcStructGeom ya los
    //    degrado a color plano por cara y salieron en la pasada 1).
    var hayTex = false;
    for (i = 0; i < pendientes.length; i++) if (cuerpoDe(pendientes[i]).malla.texCount) hayTex = true;
    if (hayTex && mc.structAtlasTex && mc.stexProg) {
      var TL = mc.stexLoc, tstr = 10 * 4;
      gl.useProgram(mc.stexProg);
      gl.uniformMatrix4fv(TL.uProj, false, pj.m);
      gl.uniform3f(TL.uSky, MC_SKY[0], MC_SKY[1], MC_SKY[2]);
      gl.uniform1f(TL.uFogNear, pj.far * 0.55); gl.uniform1f(TL.uFogFar, pj.far * 0.98);
      gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, mc.structAtlasTex); gl.uniform1i(TL.uTex, 0);
      mcAttribs([TL.aPos, TL.aTile, TL.aRect, TL.aShade]);
      for (i = 0; i < pendientes.length; i++) {
        a = pendientes[i]; c = cuerpoDe(a);
        if (!c.malla.texCount) continue;
        gl.uniformMatrix4fv(TL.uView, false, vista(a, c));
        gl.bindBuffer(gl.ARRAY_BUFFER, c.malla.texVbo);
        gl.vertexAttribPointer(TL.aPos, 3, gl.FLOAT, false, tstr, 0);
        gl.vertexAttribPointer(TL.aTile, 2, gl.FLOAT, false, tstr, 12);
        gl.vertexAttribPointer(TL.aRect, 4, gl.FLOAT, false, tstr, 20);
        gl.vertexAttribPointer(TL.aShade, 1, gl.FLOAT, false, tstr, 36);
        gl.drawArrays(gl.TRIANGLES, 0, c.malla.texCount);
      }
    }
  }

  // Matriz MODELO de un cuerpo (local -> mundo): centrado en la celda del agente, base en renderY+1.
  // La usan las dos pasadas: la de dibujar (multiplicada por la vista) y la del SOL, que necesita la
  // posicion de mundo para meter el cuerpo en el mapa de sombra.
  function modelo(a, c) {
    var rx = a.renderX !== undefined ? a.renderX : a.x;
    var ry = a.renderY !== undefined ? a.renderY : a.y;
    var rz = a.renderZ !== undefined ? a.renderZ : a.z;
    var m = c.malla;
    return mat4.translate(rx + 0.5 - m.ext.x / 2, ry + 1, rz + 0.5 - m.ext.z / 2);
  }

  // Los cuerpos de ESTRUCTURA los dibuja esta libreria, no app.js, asi que no estan en ninguna de las
  // listas que barre la pasada del sol. mc.sunExtra es el gancho generico que app.js ofrece para eso:
  // le presta su dibujante ya configurado y aqui se le pasan las mismas VBO con su matriz de modelo.
  // Sin esto un agente con cuerpo de estructura se veria flotando sin proyectar nada.
  function proyectarCuerposEstructura(dibuja) {
    if (typeof mc === 'undefined' || !mc.agents) return;
    mc.agents.forEach(function (a) {
      var c = cuerpoDe(a);
      if (!c || !c.malla || a.state === 'stopped') return;
      var m = modelo(a, c);
      dibuja(c.malla.colVbo, c.malla.colCount, 9 * 4, m);
      dibuja(c.malla.texVbo, c.malla.texCount, 10 * 4, m);
      // el translucido no: un cristal no proyecta un agujero negro (misma regla que app.js)
    });
  }

  function instalarGanchosCuerpo() {
    if (cuerposInstalado) return;
    if (typeof mcAgentMesh !== 'function' || typeof mcRender !== 'function') {
      console.warn('game.skills.cuerpo: el Mundo no esta cargado todavia (no hay mcAgentMesh/mcRender).');
      return;
    }
    var mallaOriginal = mcAgentMesh;
    mcAgentMesh = function (a) {
      var c = cuerpoDe(a);
      if (!c) return mallaOriginal(a);
      // VUELO: mcAgentsSmoothUpdate acaba de pegar a.renderY a la superficie del terreno. Se deshace
      // aqui, que es el ultimo sitio del frame que lo toca. Como `altura` es constante, el salto solo
      // ocurre en el primer frame (a partir de ahi renderY ya venia de aqui) y no descoloca a nadie
      // que vaya montado encima.
      if (c.altura !== null && c.altura !== undefined) a.renderY = c.altura - 1;
      if (c.tipo === 'estructura') {
        a.count = 0;                                          // lo dibuja dibujarCuerposEstructura()
        if (typeof mcShadowDirty === 'function') mcShadowDirty();   // ...y lo proyecta proyectarCuerposEstructura()
        return;
      }
      return mallaCuboEscalado(a, c);
    };
    var renderOriginal = mcRender;
    mcRender = function () {
      renderOriginal();
      try { dibujarCuerposEstructura(); }
      catch (e) { console.error('[skills.cuerpo] pasada de cuerpos de estructura:', e); }
    };
    if (typeof mc !== 'undefined' && 'sunExtra' in mc) mc.sunExtra = proyectarCuerposEstructura;
    cuerposInstalado = true;
  }

  // game.skills.cuerpo(a, opciones) · da a un agente un cuerpo propio.
  //   bloque:     clave o alias de material (mismo formato que cfg.block). Cubo del atlas.
  //   estructura: clave de la galeria ('hab:nube', 'asset:assets/x.vox.json'). Voxeles finos.
  //   escala:     tamano del cuerpo en bloques (1 = como siempre). Admite decimales.
  //   altura:     Y de la BASE del cuerpo. Con altura, el agente VUELA (deja de pegarse al suelo).
  // Devuelve una promesa si el cuerpo es de estructura (hay que descargar y mallar la sala).
  game.skills.cuerpo = function (a, opciones) {
    if (!a || !a.vars) { console.warn('game.skills.cuerpo: pasa el handle del agente.'); return null; }
    var op = opciones || {};
    instalarGanchosCuerpo();
    if (!cuerposInstalado) return null;
    var previo = cuerpoDe(a);
    if (previo && previo.malla) liberarMallaEstructura(previo.malla);
    var escala = isFinite(+op.escala) && +op.escala > 0 ? +op.escala : 1;
    var altura = isFinite(+op.altura) ? +op.altura : null;
    var c = { tipo: op.estructura ? 'estructura' : 'bloque', escala: escala, altura: altura,
              estructura: op.estructura || null, malla: null };
    a.vars._cuerpo = c;
    if (c.tipo === 'bloque') {
      if (op.bloque != null) { a.block = op.bloque; a.blockId = mcResolveMat(op.bloque); }
      mcAgentMesh(a);
      return null;
    }
    a.count = 0;
    return construirMallaEstructura(a, c).then(function (m) {
      if (a.vars._cuerpo !== c) { liberarMallaEstructura(m); return null; }   // redefinido mientras cargaba
      c.malla = m;
      if (m && !m.colCount && !m.alphaCount && !m.texCount)
        console.warn('game.skills.cuerpo("' + a.id + '"): la estructura "' + c.estructura + '" no tiene voxeles.');
      return a;
    }, function (err) {
      console.error('[skills.cuerpo] no se pudo mallar "' + c.estructura + '":', err);
      return null;
    });
  };

  // Suelta las VBO del cuerpo de estructura (llamalo en onStop si creas y destruyes agentes a menudo).
  game.skills.liberarCuerpo = function (a) {
    var c = cuerpoDe(a);
    if (c && c.malla) { liberarMallaEstructura(c.malla); c.malla = null; }
    if (a.vars) a.vars._solido = false;
    return a;
  };



  // ============================================================================================
  // CUERPO SOLIDO: la fisica del agente a su TAMANO REAL (chocar, empujar, subirse encima)
  // ============================================================================================
  // app.js le da a TODO agente la misma caja de fisica: 1x1x1 en [rx,rx+1] x [ry+1,ry+2) x [rz,rz+1].
  // Por eso un cuerpo a escala 9 se VE enorme y se CHOCA diminuto, y subirse encima de una nube es
  // buscar un pixel invisible. La caja esta cableada en tres sitios:
  //
  //   mcCollides   (app.js) — con que choca el jugador.
  //   mcAgentShove (app.js) — el empujon cuando un agente te embiste.
  //   a.isMounted  (app.js) — ir montado encima; su ventana es [ry+1.9, ry+2.5], la tapa de un cubo de 1.
  //
  // Los tres se corrigen DESDE AQUI, sin tocar app.js (§0): los dos primeros son funciones globales y se
  // envuelven igual que mcAgentMesh o mcSerialize; el tercero es un metodo del handle y se reemplaza.
  //
  // El agente sigue siendo un agente normal del framework, con toda su mecanica: se mueve interpolado
  // entre celdas (suave, no a trompicones), te empuja si te embiste y te lleva encima. Lo unico que
  // cambia es que la medida que usa la fisica es la de verdad, no un 1x1x1 fijo.
  //
  // La caja sale del cuerpo que ya declaraste con skills.cuerpo (escala/altura): lo que se VE y lo que
  // se CHOCA son la misma medida, no dos verdades que hay que mantener a la vez.
  //
  //   game.skills.cuerpo(a, { bloque:'nube-snow', escala:9, altura:26 });
  //   game.skills.solido(a);          // ahora choca, empuja y te lleva a escala 9
  //   game.skills.solido(a, false);   // vuelve al 1x1x1 del framework

  var solidoInstalado = false;
  var SIN_AGENTES = new Map();       // Map vacio: el original hace `if(mc.agents && mc.agents.size)`

  // Caja REAL del cuerpo, en las mismas cotas que mallaCuboEscalado: centrada en la celda y apoyada
  // en renderY+1 (que para un agente con `altura` es la altura de vuelo, ver el gancho de arriba).
  function cajaSolida(a) {
    if (!a || !a.vars || !a.vars._solido) return null;
    var c = cuerpoDe(a);
    if (!c) return null;
    var k = c.escala;
    var rx = a.renderX !== undefined ? a.renderX : a.x;
    var ry = a.renderY !== undefined ? a.renderY : a.y;
    var rz = a.renderZ !== undefined ? a.renderZ : a.z;
    return { x0: rx + 0.5 - k / 2, x1: rx + 0.5 + k / 2,
             y0: ry + 1,           y1: ry + 1 + k,
             z0: rz + 0.5 - k / 2, z1: rz + 0.5 + k / 2 };
  }

  // La del framework, para el agente que no ha pedido cuerpo solido: no se le cambia nada.
  function cajaAgente(a) {
    var b = cajaSolida(a);
    if (b) return b;
    var rx = a.renderX !== undefined ? a.renderX : a.x;
    var ry = a.renderY !== undefined ? a.renderY : a.y;
    var rz = a.renderZ !== undefined ? a.renderZ : a.z;
    return { x0: rx, x1: rx + 1, y0: ry + 1, y1: ry + 2, z0: rz, z1: rz + 1 };
  }

  function solapa(b, minX, maxX, minY, maxY, minZ, maxZ) {
    return maxX > b.x0 && minX < b.x1 && maxY > b.y0 && minY < b.y1 && maxZ > b.z0 && minZ < b.z1;
  }

  function instalarGanchosSolido() {
    if (solidoInstalado) return;
    if (typeof mcCollides !== 'function' || typeof mcAgentShove !== 'function') {
      console.warn('game.skills.solido: el Mundo no esta cargado todavia.');
      return;
    }

    // COLISION. Al original se le ESCONDEN los agentes (mc.agents vacio => se salta ese bloque entero)
    // para quedarnos solo con terreno + estructuras, y las cajas de los agentes se ponen aqui con la
    // medida buena. Sin esconderlos, la caja 1x1x1 seguiria ahi: en un agente que vuela es un obstaculo
    // invisible a ras de suelo, justo debajo de la nube.
    var colisionPrevia = mcCollides;
    mcCollides = function (px, py, pz) {
      var guardados = mc.agents;
      mc.agents = SIN_AGENTES;
      var hit;
      try { hit = colisionPrevia(px, py, pz); } finally { mc.agents = guardados; }
      if (hit) return true;
      if (!mc.agents || !mc.agents.size) return false;
      var HW = MC_HW * mc.scale, PH = MC_PH * mc.scale;
      var minX = px - HW, maxX = px + HW, minY = py, maxY = py + PH - 1e-4, minZ = pz - HW, maxZ = pz + HW;
      var it = mc.agents.values(), n;
      while (!(n = it.next()).done) {
        var a = n.value;
        if (a.state === 'stopped') continue;
        if (solapa(cajaAgente(a), minX, maxX, minY, maxY, minZ, maxZ)) return true;
      }
      return false;
    };

    // EMPUJON. Misma politica que app.js (salir por la salida horizontal mas corta A FAVOR de la marcha
    // del agente; si esta parado, radialmente desde su centro), pero contra la caja real. Los agentes sin
    // cuerpo solido no se tocan: los resuelve el original.
    var empujonPrevio = mcAgentShove;
    mcAgentShove = function () {
      if (!mc.agents || !mc.agents.size) return false;
      var p = mc.pos, HW = MC_HW * mc.scale, PH = MC_PH * mc.scale, eps = 1e-3;
      var minX = p[0] - HW, maxX = p[0] + HW, minY = p[1], maxY = p[1] + PH - 1e-4;
      var minZ = p[2] - HW, maxZ = p[2] + HW;
      var it = mc.agents.values(), n;
      while (!(n = it.next()).done) {
        var a = n.value;
        if (a.state === 'stopped') continue;
        var b = cajaSolida(a);
        if (!b || !solapa(b, minX, maxX, minY, maxY, minZ, maxZ)) continue;
        var rx = a.renderX !== undefined ? a.renderX : a.x;
        var rz = a.renderZ !== undefined ? a.renderZ : a.z;
        var hx = a.x - rx, hz = a.z - rz;
        if (Math.abs(hx) < 1e-4 && Math.abs(hz) < 1e-4) { hx = p[0] - (b.x0 + b.x1) / 2; hz = p[2] - (b.z0 + b.z1) / 2; }
        var salidas = [{ dx: (b.x0 - HW - eps) - p[0], dz: 0 }, { dx: (b.x1 + HW + eps) - p[0], dz: 0 },
                       { dx: 0, dz: (b.z0 - HW - eps) - p[2] }, { dx: 0, dz: (b.z1 + HW + eps) - p[2] }];
        for (var i = 0; i < 4; i++) {
          var s = salidas[i];
          s.dist = Math.abs(s.dx) + Math.abs(s.dz);
          s.contra = (s.dx * hx + s.dz * hz) > 0 ? 0 : 1;
        }
        salidas.sort(function (u, v) { return (u.contra - v.contra) || (u.dist - v.dist); });
        for (var j = 0; j < 4; j++) {
          var nx = p[0] + salidas[j].dx, nz = p[2] + salidas[j].dz;
          if (mcCollides(nx, p[1], nz)) continue;
          p[0] = nx; p[2] = nz; return true;
        }
        return false;                     // acorralado: que mcUnstick haga lo de siempre
      }
      return empujonPrevio();
    };

    solidoInstalado = true;
  }

  // game.skills.solido(a[, activo]) · la fisica del agente pasa a ser la de su cuerpo real.
  // Exige haber llamado antes a game.skills.cuerpo(a, ...): de ahi salen la escala y la altura.
  game.skills.solido = function (a, activo) {
    if (!a || !a.vars) { console.warn('game.skills.solido: pasa el handle del agente.'); return null; }
    if (activo === false) {
      a.vars._solido = false;
      if (a._montarPrevio) { a.isMounted = a._montarPrevio; a._montarPrevio = null; }
      return a;
    }
    if (!cuerpoDe(a)) {
      console.warn('game.skills.solido("' + a.id + '"): el agente no tiene cuerpo declarado. Llama antes a '
                 + 'game.skills.cuerpo(a, { escala:..., altura:... }).');
      return null;
    }
    instalarGanchosSolido();
    if (!solidoInstalado) return null;
    a.vars._solido = true;
    if (!a._montarPrevio) a._montarPrevio = a.isMounted;
    // MONTAR. El original mira la ventana [ry+1.9, ry+2.5] porque su cuerpo mide 1: los pies del que va
    // encima estan en la TAPA del cuerpo + un pelo. Con la caja real la tapa es b.y1, y nada mas.
    a.isMounted = function () {
      if (a._dismountedAt && (performance.now() - a._dismountedAt < 2500)) return false;
      var b = cajaSolida(a);
      if (!b) return a._montarPrevio ? a._montarPrevio() : false;
      var p = mc.pos;
      // apoyado en suelo del mundo = no vas montado (igual que el original)
      var px = Math.floor(p[0]), py = Math.floor(p[1]), pz = Math.floor(p[2]);
      if (typeof mcGetVoxel === 'function' && mcGetVoxel(px, py - 1, pz) > 0) return false;
      return p[0] >= b.x0 && p[0] <= b.x1 && p[2] >= b.z0 && p[2] <= b.z1
          && p[1] >= b.y1 - 0.1 && p[1] <= b.y1 + 0.6;
    };
    return a;
  };

  // LIMITACION honesta: para un cuerpo de ESTRUCTURA la caja es el cubo de lado `escala`, no la silueta
  // fina de la malla. Una estructura con huecos se choca como si fuera maciza. Afinarlo pediria muestrear
  // mcStructGeom por celda, que es lo que hace mcFineBoxHit con las salas — y eso si tocaria app.js.

  // ============================================================================================
  // ============================================================================================
  // SOMBRA: ya no vive aqui - la hace el motor, para TODO el mundo a la vez
  // ============================================================================================
  // Aqui hubo ~420 lineas: un ocluso efimero metido en mc.grid, mcComputeLight relanzado entero para
  // diffear niveles, un campo de transmitancia 3D, un quad por cara, alpha remuestreado bilinealmente y
  // una pasada de dibujo con su propio blendFuncSeparate. Todo eso existia por una sola razon: el agente
  // no esta en mc.grid, asi que no entraba en el calculo de sombras del mundo y habia que fabricarsela.
  //
  // Ahora app.js tiene un MAPA DE SOMBRA (mcRenderShadow): se renderiza el mundo desde el sol a una
  // textura y cada fragmento consulta si hay algo por encima. Le entran las MISMAS VBO que se dibujan en
  // pantalla, asi que el cuerpo del agente proyecta sombra por el mero hecho de dibujarse - sin una linea
  // de codigo aqui, con resolucion de subcelda (se desliza, no da trompicones) y sobre las seis caras de
  // lo que sea que este debajo. De paso se fueron los dos fallos que traia la estampa: las esquinas sin
  // sombrear (era el alpha desvaneciendose en el borde del quad + SOMBRA_EPS) y las zonas mas claras del
  // suelo junto a un bloque (era el bilineal promediando celdas solidas).
  //
  // Lo unico que queda es el interruptor, y solo por compatibilidad: apagarle la sombra a un agente suelto
  // ya no significa nada. Si se dibuja, proyecta. Para quitarla del todo esta game.sunShade = 1.
  var avisoSombra = false;
  game.skills.sombra = function (a, activo) {
    if (!a || !a.vars) { console.warn('game.skills.sombra: pasa el handle del agente.'); return null; }
    if (!avisoSombra) {
      avisoSombra = true;
      console.info('[skills.sombra] la sombra la hace el motor (mapa de sombra del sol): todo lo que se '
        + 'dibuja proyecta. Este interruptor ya no hace nada; para regularla, game.sunShade (1 = sin sombra).');
    }
    a.vars._sombraOff = (activo === false);   // se conserva por si un snippet viejo lo lee
    return a;
  };

})();
